import { Injectable, Logger } from '@nestjs/common';
import type { Socket } from 'net';
import type { TLSSocket } from 'tls';

/**
 * Minimal SMTP client (zero dependencies).
 *   - SMTP_SECURE=true  → implicit TLS (port 465)
 *   - SMTP_SECURE=false → plain connect, opportunistic STARTTLS (port 587)
 * Configure via env: SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASS, SMTP_FROM.
 * If SMTP_HOST is unset, send() no-ops with a log — digests still land in the
 * notification queue so nothing is lost when credentials arrive later.
 */
@Injectable()
export class MailerService {
  private readonly logger = new Logger(MailerService.name);

  private get config() {
    return {
      host: process.env.SMTP_HOST,
      port: parseInt(process.env.SMTP_PORT || '587', 10),
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
      from: process.env.SMTP_FROM || 'BastionOS <ops@spectra.technology>',
      secure: process.env.SMTP_SECURE === 'true',
    };
  }

  get isConfigured(): boolean {
    return Boolean(this.config.host);
  }

  /**
   * A tiny SMTP conversation helper: sends commands, buffers lines, and
   * resolves each awaited command when a complete SMTP response arrives
   * (line 3 is a space). Swappable socket so STARTTLS upgrades are trivial.
   */
  private createSession(socket: Socket | TLSSocket) {
    let buffer = '';
    const waiters: Array<(resp: string) => void> = [];

    const onData = (chunk: Buffer) => {
      buffer += chunk.toString('utf8');
      let idx: number;
      while ((idx = buffer.indexOf('\r\n')) !== -1) {
        const line = buffer.slice(0, idx);
        buffer = buffer.slice(idx + 2);
        const code = line.slice(0, 3);
        const complete = line.length > 3 && line[3] === ' ';
        if (complete && waiters.length > 0) {
          waiters.shift()!(line);
        }
        // keep the code for multi-line continuation check
        void code;
      }
    };

    socket.on('data', onData);

    const session = {
      socket,
      command: (cmd: string): Promise<string> =>
        new Promise((resolve) => {
          waiters.push(resolve);
          socket.write(cmd + '\r\n');
        }),
      waitForGreeting: (): Promise<void> =>
        new Promise((resolve) => {
          waiters.push(() => resolve());
        }),
      destroy: () => socket.removeListener('data', onData),
    };

    return session;
  }

  async send(opts: {
    to: string | string[];
    subject: string;
    text: string;
    html?: string;
  }): Promise<void> {
    if (!this.isConfigured) {
      this.logger.warn(
        `SMTP not configured — skipping email "${opts.subject}"`,
      );
      return;
    }

    const net = require('net');
    const tls = require('tls');
    const { host, port, secure, user, pass, from } = this.config;

    let socket: Socket | TLSSocket = secure
      ? tls.connect({ host, port })
      : net.connect({ host, port });

    await new Promise<void>((resolve, reject) => {
      socket.once('connect', () => resolve());
      socket.once('error', reject);
    });

    const session = this.createSession(socket);
    let lastCode = '';

    try {
      await session.waitForGreeting();
      lastCode = (await session.command('EHLO bastion.local')).slice(0, 3);

      // Opportunistic STARTTLS on plain connections
      if (!secure && lastCode === '250' && (user || pass)) {
        const resp = await session.command('STARTTLS');
        if (resp.startsWith('220')) {
          const upgraded: TLSSocket = await new Promise((resolve, reject) => {
            const tlsSocket = tls.connect({
              socket,
              rejectUnauthorized: false,
            });
            tlsSocket.once('secureConnect', () => resolve(tlsSocket));
            tlsSocket.once('error', reject);
          });
          session.destroy();
          socket = upgraded;
          const upgradedSession = this.createSession(socket);
          await upgradedSession.waitForGreeting();
          await upgradedSession.command('EHLO bastion.local');
          await this.auth(upgradedSession, user!, pass!);
          await this.sendMail(upgradedSession, { ...opts, from });
          await upgradedSession.command('QUIT');
          upgradedSession.destroy();
          socket.end();
          return;
        }
      }

      if (user && pass) await this.auth(session, user, pass);
      await this.sendMail(session, { ...opts, from });
      await session.command('QUIT');
      this.logger.log(`Email sent: "${opts.subject}"`);
    } finally {
      session.destroy();
      socket.end();
    }
  }

  private async auth(session: any, user: string, pass: string) {
    const a = await session.command('AUTH LOGIN');
    if (!a.startsWith('334')) {
      // Try PLAIN as a fallback
      const plain = Buffer.from(`\0${user}\0${pass}`).toString('base64');
      const r = await session.command(`AUTH PLAIN ${plain}`);
      if (!r.startsWith('235')) throw new Error(`SMTP auth failed: ${r}`);
      return;
    }
    await session.command(Buffer.from(user).toString('base64'));
    const r = await session.command(Buffer.from(pass).toString('base64'));
    if (!r.startsWith('235')) throw new Error(`SMTP auth failed: ${r}`);
  }

  private async sendMail(
    session: any,
    opts: {
      from: string;
      to: string | string[];
      subject: string;
      text: string;
      html?: string;
    },
  ) {
    const recipients = Array.isArray(opts.to) ? opts.to : [opts.to];
    const fromAddr = opts.from.replace(/^.*<|>$/g, '').trim();

    await session.command(`MAIL FROM:<${fromAddr}>`);
    for (const to of recipients) {
      const resp = await session.command(`RCPT TO:<${to}>`);
      if (!resp.startsWith('2')) throw new Error(`RCPT rejected: ${resp}`);
    }
    await session.command('DATA');

    const headers = [
      `From: ${opts.from}`,
      `To: ${recipients.join(', ')}`,
      `Subject: ${opts.subject}`,
      'MIME-Version: 1.0',
      `Content-Type: ${opts.html ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8'}`,
      '',
    ].join('\r\n');

    const body = (opts.html ?? opts.text).replace(/\r?\n/g, '\r\n');
    socketWrite(session, headers + '\r\n' + body + '\r\n.\r\n');
    await new Promise((resolve) => setTimeout(resolve, 1200));
  }
}

function socketWrite(session: any, data: string) {
  session.socket.write(data);
}

import { config } from 'dotenv';
import { resolve } from 'path';

// Load .env before anything else (__dirname is dist/src/, go up 2 levels to backend root)
config({ path: resolve(__dirname, '..', '..', '.env'), override: true });

import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe, Logger } from '@nestjs/common';
import cookieParser from 'cookie-parser';
import { NestExpressApplication } from '@nestjs/platform-express';
import { join } from 'path';
import { mkdirSync, existsSync } from 'fs';
import { SecurityMiddleware } from './common/security.middleware';

async function bootstrap() {
  // Ensure uploads directory exists
  const uploadsDir = join(process.cwd(), 'uploads');
  if (!existsSync(uploadsDir)) {
    mkdirSync(uploadsDir, { recursive: true });
  }
  if (!process.env.JWT_SECRET) {
    throw new Error('JWT_SECRET is required');
  }

  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    logger: ['log', 'error', 'warn', 'debug', 'verbose'],
  });

  // Behind a platform proxy (Render, Vercel, nginx) the socket address is the
  // proxy. Trust the first hop so req.ip — used for rate limiting and lead
  // attribution — is the real client address.
  app.set('trust proxy', 1);

  app.use(cookieParser());

  // Security hardening: headers + auth rate limiting
  const security = new SecurityMiddleware();
  app.use((req: any, res: any, next: any) => security.use(req, res, next));
  setInterval(() => security.prune(), 60 * 1000).unref();

  // Log all requests with full error details
  const httpLogger = new Logger('HTTP');
  app.use((req: any, res: any, next: any) => {
    const start = Date.now();
    const originalJson = res.json.bind(res);
    let responseBody: any = null;

    // Intercept JSON responses to capture error details
    res.json = (body: any) => {
      responseBody = body;
      return originalJson(body);
    };

    res.on('finish', () => {
      const { statusCode } = res;
      const ms = Date.now() - start;
      const details =
        statusCode >= 400 && responseBody
          ? ` | ${JSON.stringify(responseBody).substring(0, 200)}`
          : '';

      if (statusCode >= 500) {
        httpLogger.error(
          `${req.method} ${req.originalUrl} → ${statusCode} (${ms}ms)${details}`,
          statusCode >= 500 ? responseBody?.stack : undefined,
        );
      } else if (statusCode >= 400) {
        httpLogger.warn(
          `${req.method} ${req.originalUrl} → ${statusCode} (${ms}ms)${details}`,
        );
      } else {
        httpLogger.log(
          `${req.method} ${req.originalUrl} → ${statusCode} (${ms}ms)`,
        );
      }
    });
    next();
  });

  // Serve uploaded media files statically
  app.useStaticAssets(join(process.cwd(), 'uploads'), { prefix: '/uploads' });

  app.setGlobalPrefix('api/v1');
  app.enableCors({
    origin:
      process.env.CORS_ORIGIN?.split(',').map((origin) => origin.trim()) ??
      false,
    credentials: true,
  });

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      transform: true,
      forbidNonWhitelisted: true,
    }),
  );

  await app.listen(process.env.PORT ?? 3001);
}
bootstrap();

import {
  Injectable,
  BadRequestException,
  ForbiddenException,
  NotFoundException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { RealtimeService } from '../realtime/realtime.service';
import { CheckInDto, CheckOutDto } from './dto/attendance.dto';

@Injectable()
export class AttendanceService {
  constructor(
    private prisma: PrismaService,
    private realtime: RealtimeService,
  ) {}

  // Distance calculation using Haversine formula
  private getDistance(
    lat1: number,
    lon1: number,
    lat2: number,
    lon2: number,
  ): number {
    const R = 6371e3; // metres
    const φ1 = (lat1 * Math.PI) / 180;
    const φ2 = (lat2 * Math.PI) / 180;
    const Δφ = ((lat2 - lat1) * Math.PI) / 180;
    const Δλ = ((lon2 - lon1) * Math.PI) / 180;

    const a =
      Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
      Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

    return R * c; // in metres
  }

  private async resolveGuardAndSite(
    dto: { guardId?: string; siteId?: string },
    user: { id: string; role: string; organizationId: string },
  ) {
    const guardId =
      dto.guardId ??
      (
        await this.prisma.guard.findUnique({
          where: { userId: user.id },
          select: { id: true },
        })
      )?.id;
    if (!guardId)
      throw new NotFoundException('Guard profile not found for this employee');

    const guard = await this.prisma.guard.findFirst({
      where: { id: guardId, organizationId: user.organizationId },
    });
    if (!guard) throw new NotFoundException('Guard not found');

    const siteId = dto.siteId ?? guard.assignedSiteId;
    if (!siteId)
      throw new BadRequestException('Guard is not assigned to a site');

    const site = await this.prisma.site.findFirst({
      where: { id: siteId, organizationId: user.organizationId },
    });
    if (!site) throw new NotFoundException('Site not found');

    if (guard.assignedSiteId && guard.assignedSiteId !== site.id) {
      throw new ForbiddenException('Guard is not assigned to this site');
    }

    return { guard, site };
  }

  async checkIn(
    dto: CheckInDto,
    user: { id: string; role: string; organizationId: string },
  ) {
    // 1. Verify site and guard exist
    const { guard, site } = await this.resolveGuardAndSite(dto, user);

    // 2. Check if guard is already checked in today without checking out
    const now = new Date();
    const today = new Date(now);
    today.setHours(0, 0, 0, 0);

    const existingRecord = await this.prisma.attendance.findFirst({
      where: {
        guardId: guard.id,
        createdAt: { gte: today },
        checkOutTime: null,
      },
    });

    if (existingRecord) {
      throw new BadRequestException('Guard is already checked in.');
    }

    // 3. Shift-aware validation: determine expected check-in window
    let isLate = false;
    if (guard.currentShift === 'DAY') {
      // Day shift expected check-in: 05:00 - 08:00
      const hour = now.getHours();
      if (hour > 8) isLate = true;
    } else if (guard.currentShift === 'NIGHT') {
      // Night shift expected check-in: 17:00 - 20:00
      const hour = now.getHours();
      if (hour > 20 || hour < 5) isLate = true;
    }

    // 4. Geofence Check (must be within 200 meters of the site)
    const distance = this.getDistance(
      site.latitude,
      site.longitude,
      dto.latitude,
      dto.longitude,
    );
    const isWithinGeofence = distance <= 200; // 200m radius

    // 5. Determine status
    let status = 'ON_TIME';
    if (!isWithinGeofence) {
      status = 'FLAGGED';
    } else if (isLate) {
      status = 'LATE';
    }

    // 6. Create attendance record
    const record = await this.prisma.attendance.create({
      data: {
        guardId: guard.id,
        siteId: site.id,
        checkInTime: now,
        checkInLatitude: dto.latitude,
        checkInLongitude: dto.longitude,
        checkInLocation: JSON.stringify({
          lat: dto.latitude,
          lng: dto.longitude,
        }),
        checkInMethod: 'GPS',
        status,
        photoUrl: dto.photoUrl ?? '',
        verifiedStatus: isWithinGeofence,
        isLate,
      },
    });

    // 7. Update guard performance score based on attendance rate
    await this.updateGuardPerformanceScore(guard.id);

    // Real-time check-in event for the command center
    this.realtime.publish(user.organizationId, 'attendance:checkin', {
      id: record.id,
      guardId: guard.id,
      guardName: guard.fullName,
      siteId: site.id,
      siteName: site.name,
      status,
      isLate,
      withinGeofence: isWithinGeofence,
      time: record.checkInTime.toISOString(),
    });

    // 8. Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: user.id,
          action: 'ATTENDANCE_CHECK_IN',
          entity: 'Attendance',
          entityId: record.id,
          newValues: JSON.stringify({
            guardId: guard.id,
            siteId: site.id,
            status,
            isLate,
            withinGeofence: isWithinGeofence,
          }),
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return record;
  }

  async checkOut(
    dto: CheckOutDto,
    user: { id: string; role: string; organizationId: string },
  ) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const { guard, site } = await this.resolveGuardAndSite(dto, user);

    const record = await this.prisma.attendance.findFirst({
      where: {
        guardId: guard.id,
        createdAt: { gte: today },
        checkOutTime: null,
      },
    });

    if (!record) {
      throw new BadRequestException('No active check-in found for today.');
    }

    // Geofence check on checkout too (must be within 200m)
    const distance = this.getDistance(
      site.latitude,
      site.longitude,
      dto.latitude,
      dto.longitude,
    );
    const isWithinGeofence = distance <= 200;

    return this.prisma.attendance.update({
      where: { id: record.id },
      data: {
        checkOutTime: new Date(),
        checkOutLatitude: dto.latitude,
        checkOutLongitude: dto.longitude,
        checkOutLocation: JSON.stringify({
          lat: dto.latitude,
          lng: dto.longitude,
        }),
        checkOutMethod: isWithinGeofence ? 'GPS' : 'SUPERVISOR_APPROVAL',
        verifiedStatus: record.verifiedStatus && isWithinGeofence,
      },
    });
  }

  /**
   * Recalculate and update a guard's performance score based on attendance records.
   * Scoring: 70% attendance rate, with penalties for absences and late arrivals.
   */
  private async updateGuardPerformanceScore(guardId: string): Promise<void> {
    const totalRecords = await this.prisma.attendance.count({
      where: { guardId },
    });
    if (totalRecords === 0) return;

    const lateCount = await this.prisma.attendance.count({
      where: { guardId, isLate: true },
    });
    const flaggedCount = await this.prisma.attendance.count({
      where: { guardId, status: 'FLAGGED' },
    });

    // Rate: (on-time / total) * 100, then penalize for flagged check-ins
    const onTimeCount = totalRecords - lateCount;
    const baseRate = (onTimeCount / totalRecords) * 100;
    const penalty = flaggedCount * 2; // -2 points per geofence violation
    const finalScore = Math.max(
      0,
      Math.min(100, Math.round(baseRate - penalty)),
    );

    await this.prisma.guard.update({
      where: { id: guardId },
      data: { performanceScore: finalScore },
    });
  }

  /**
   * Detect and mark guards as absent for a given date.
   * A guard is absent if they have no check-in record for the date and are ACTIVE.
   */
  async markAbsentGuards(
    organizationId: string,
    date?: string,
  ): Promise<number> {
    const targetDate = date ? new Date(date) : new Date();
    const startOfDay = new Date(targetDate);
    startOfDay.setHours(0, 0, 0, 0);
    const endOfDay = new Date(targetDate);
    endOfDay.setHours(23, 59, 59, 999);

    // Find all active guards who have no attendance record for this day
    const activeGuards = await this.prisma.guard.findMany({
      where: { organizationId, status: 'ACTIVE' },
      select: { id: true },
    });

    let absentCount = 0;
    for (const guard of activeGuards) {
      const hasAttendance = await this.prisma.attendance.findFirst({
        where: {
          guardId: guard.id,
          checkInTime: { gte: startOfDay, lte: endOfDay },
        },
      });
      if (!hasAttendance) {
        // Fetch full guard data to get assigned site
        const fullGuard = await this.prisma.guard.findUnique({
          where: { id: guard.id },
          select: { assignedSiteId: true },
        });
        // Create an absent record
        await this.prisma.attendance.create({
          data: {
            guardId: guard.id,
            siteId: fullGuard?.assignedSiteId || '',
            checkInTime: startOfDay,
            checkInLatitude: 0,
            checkInLongitude: 0,
            checkInMethod: 'GPS',
            status: 'ABSENT',
            isAbsent: true,
          },
        });
        absentCount++;
      }
    }

    return absentCount;
  }

  async getAttendanceHistory(query: {
    page?: number;
    limit?: number;
    siteId?: string;
    date?: string;
    guardId?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 20;
    const skip = (page - 1) * limit;

    const where: any = { guard: { organizationId: query.organizationId } };
    if (query.siteId) where.siteId = query.siteId;
    if (query.guardId) where.guardId = query.guardId;
    if (query.date) {
      const startOfDay = new Date(query.date);
      startOfDay.setHours(0, 0, 0, 0);
      const endOfDay = new Date(query.date);
      endOfDay.setHours(23, 59, 59, 999);
      where.createdAt = { gte: startOfDay, lte: endOfDay };
    }

    const [data, total] = await Promise.all([
      this.prisma.attendance.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: {
          guard: { select: { id: true, fullName: true, currentShift: true } },
          site: { select: { id: true, name: true } },
        },
      }),
      this.prisma.attendance.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }

  /** Export attendance records as CSV for payroll / compliance. */
  async exportCsv(opts: {
    organizationId: string;
    date?: string;
    siteId?: string;
  }) {
    const where: any = { guard: { organizationId: opts.organizationId } };
    if (opts.siteId) where.siteId = opts.siteId;
    if (opts.date) {
      const startOfDay = new Date(opts.date);
      startOfDay.setHours(0, 0, 0, 0);
      const endOfDay = new Date(opts.date);
      endOfDay.setHours(23, 59, 59, 999);
      where.createdAt = { gte: startOfDay, lte: endOfDay };
    }

    const records = await this.prisma.attendance.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      include: {
        guard: { select: { fullName: true, nin: true, currentShift: true } },
        site: { select: { name: true } },
      },
    });

    const header = [
      'Date',
      'Guard Name',
      'NIN',
      'Site',
      'Check In',
      'Check Out',
      'Status',
      'Late',
      'Shift',
    ];
    const escape = (v: unknown) => {
      const s = String(v ?? '');
      return /[,"\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    };
    const rows = records.map((r) =>
      [
        r.createdAt.toLocaleDateString('en-GB'),
        r.guard.fullName,
        r.guard.nin,
        r.site.name,
        r.checkInTime?.toLocaleString('en-GB'),
        r.checkOutTime?.toLocaleString('en-GB') ?? '',
        r.status,
        r.isLate ? 'YES' : 'NO',
        r.guard.currentShift,
      ]
        .map(escape)
        .join(','),
    );

    return [header.join(','), ...rows].join('\r\n');
  }
}

import { IsString, IsNotEmpty, IsNumber, IsOptional } from 'class-validator';

export class CheckInDto {
  @IsString() @IsOptional() guardId?: string;
  @IsString() @IsOptional() siteId?: string;
  @IsNumber() latitude: number;
  @IsNumber() longitude: number;
  @IsString() @IsOptional() photoUrl?: string;
}

export class CheckOutDto {
  @IsString() @IsOptional() guardId?: string;
  @IsNumber() latitude: number;
  @IsNumber() longitude: number;
  @IsString() @IsOptional() report?: string;
}

import {
  CallHandler,
  ExecutionContext,
  Injectable,
  NestInterceptor,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { AuditService } from './audit.service';

/**
 * Global interceptor: records every mutating request (POST/PATCH/PUT/DELETE)
 * into the AuditLog table with actor, entity, IP and user agent.
 */
@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(private readonly auditService: AuditService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const req = context.switchToHttp().getRequest();
    const method = req?.method;
    if (!method || !['POST', 'PATCH', 'PUT', 'DELETE'].includes(method)) {
      return next.handle();
    }

    const route = req?.route?.path ?? req?.url ?? 'unknown';
    const entityId =
      req?.params?.id ??
      req?.params?.guardId ??
      req?.params?.siteId ??
      req?.params?.clientId ??
      req?.params?.incidentId ??
      '';

    return next.handle().pipe(
      tap((response) => {
        const createdId =
          response?.id ??
          response?.data?.id ??
          (Array.isArray(response) ? response[0]?.id : undefined);
        this.auditService.log({
          userId: req?.user?.id,
          action: method,
          entity: route,
          entityId: createdId ?? entityId ?? '',
          newValues: { body: req?.body },
          ipAddress: req?.ip,
          userAgent: req?.get?.('user-agent'),
        });
      }),
    );
  }
}

import {
  Controller,
  Post,
  Body,
  Get,
  Patch,
  UseGuards,
  HttpCode,
  HttpStatus,
  Req,
  Res,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { AuthService } from './auth.service';
import { TfaService } from './tfa.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';
import { JwtAuthGuard } from './guards/jwt-auth.guard';
import {
  CurrentUser,
  type AuthenticatedUser,
} from './decorators/current-user.decorator';
import { RolesGuard } from './guards/roles.guard';
import { Roles } from './decorators/roles.decorator';
import { PrismaService } from '../../database/prisma.service';

const COOKIE_OPTIONS = {
  httpOnly: true,
  secure: true,
  sameSite: 'none' as const,
  path: '/',
};

@Controller('auth')
export class AuthController {
  constructor(
    private authService: AuthService,
    private tfa: TfaService,
    private prisma: PrismaService,
  ) {}

  @Post('register')
  @HttpCode(HttpStatus.CREATED)
  async register(@Body() dto: RegisterDto) {
    return this.authService.register(dto);
  }

  @Post('employees')
  @UseGuards(JwtAuthGuard, RolesGuard)
  @Roles('ADMIN')
  @HttpCode(HttpStatus.CREATED)
  async createEmployee(
    @Body() dto: RegisterDto,
    @CurrentUser() user: AuthenticatedUser,
  ) {
    return this.authService.createEmployee(dto, user);
  }

  @Post('login')
  @HttpCode(HttpStatus.OK)
  async login(
    @Body() dto: LoginDto,
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.login(dto);

    // 2FA gate: no cookies yet, just hand back the step-two token
    if (result.requiresTwoFactor) {
      return { requiresTwoFactor: true, tfaToken: result.tfaToken };
    }

    res.cookie('access_token', result.accessToken, {
      ...COOKIE_OPTIONS,
      maxAge: 15 * 60 * 1000, // 15 minutes
    });

    res.cookie('refresh_token', result.refreshToken, {
      ...COOKIE_OPTIONS,
      maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
      path: '/api/v1/auth',
    });

    return { user: result.user };
  }

  @Post('tfa/login')
  @HttpCode(HttpStatus.OK)
  async tfaLogin(
    @Body() dto: { tfaToken: string; code: string },
    @Res({ passthrough: true }) res: Response,
  ) {
    const result = await this.authService.completeTfaLogin(
      dto.tfaToken,
      dto.code,
    );

    res.cookie('access_token', result.accessToken, {
      ...COOKIE_OPTIONS,
      maxAge: 15 * 60 * 1000,
    });

    res.cookie('refresh_token', result.refreshToken, {
      ...COOKIE_OPTIONS,
      maxAge: 7 * 24 * 60 * 60 * 1000,
      path: '/api/v1/auth',
    });

    return { user: result.user };
  }

  @Get('tfa/status')
  @UseGuards(JwtAuthGuard)
  async tfaStatus(@CurrentUser() user: AuthenticatedUser) {
    const record = await this.prisma.user.findUnique({
      where: { id: user.id },
      select: { twoFactorEnabled: true },
    });
    return { enabled: record?.twoFactorEnabled ?? false };
  }

  @Post('tfa/enable')
  @UseGuards(JwtAuthGuard)
  async tfaEnable(@CurrentUser() user: AuthenticatedUser) {
    return this.tfa.startEnrollment(user.id, user.email);
  }

  @Post('tfa/confirm')
  @UseGuards(JwtAuthGuard)
  async tfaConfirm(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: { code: string },
  ) {
    return this.tfa.confirmEnrollment(user.id, dto.code);
  }

  @Post('tfa/disable')
  @UseGuards(JwtAuthGuard)
  async tfaDisable(
    @CurrentUser() user: AuthenticatedUser,
    @Body() dto: { code: string },
  ) {
    return this.tfa.disable(user.id, dto.code);
  }

  @Post('refresh')
  @HttpCode(HttpStatus.OK)
  async refresh(
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const refreshToken = req.cookies?.refresh_token;
    const result = await this.authService.refresh(refreshToken);

    res.cookie('access_token', result.accessToken, {
      ...COOKIE_OPTIONS,
      maxAge: 15 * 60 * 1000,
    });

    res.cookie('refresh_token', result.refreshToken, {
      ...COOKIE_OPTIONS,
      maxAge: 7 * 24 * 60 * 60 * 1000,
      path: '/api/v1/auth',
    });

    return { user: result.user };
  }

  @Post('logout')
  @UseGuards(JwtAuthGuard)
  @HttpCode(HttpStatus.OK)
  async logout(
    @CurrentUser() user: AuthenticatedUser,
    @Req() req: Request,
    @Res({ passthrough: true }) res: Response,
  ) {
    const refreshToken = req.cookies?.refresh_token;
    await this.authService.logout(user.id, refreshToken);

    res.clearCookie('access_token', { ...COOKIE_OPTIONS });
    res.clearCookie('refresh_token', {
      ...COOKIE_OPTIONS,
      path: '/api/v1/auth',
    });

    return { message: 'Logged out successfully' };
  }

  @Patch('me')
  @UseGuards(JwtAuthGuard)
  async updateProfile(
    @CurrentUser() user: AuthenticatedUser,
    @Body()
    dto: {
      firstName?: string;
      lastName?: string;
      phone?: string;
      email?: string;
      photoUrl?: string;
    },
  ) {
    return this.authService.updateProfile(user.id, dto);
  }

  @Get('me')
  @UseGuards(JwtAuthGuard)
  async getMe(@CurrentUser() user: AuthenticatedUser) {
    return this.authService.getMe(user.id);
  }
}

import {
  Injectable,
  ConflictException,
  ForbiddenException,
  UnauthorizedException,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import * as bcrypt from 'bcrypt';
import * as crypto from 'crypto';
import { PrismaService } from '../../database/prisma.service';
import { TfaService } from './tfa.service';
import { RegisterDto } from './dto/register.dto';
import { LoginDto } from './dto/login.dto';

@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwtService: JwtService,
    private tfa: TfaService,
  ) {}

  async register(dto: RegisterDto) {
    const userCount = await this.prisma.user.count();
    if (userCount > 0) {
      throw new ForbiddenException(
        'Public registration is disabled. Ask an admin to create your employee account.',
      );
    }

    const existing = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (existing) {
      throw new ConflictException('Email address is already in use');
    }

    const passwordHash = await bcrypt.hash(dto.password, 10);
    const organization = await this.prisma.organization.create({
      data: { name: dto.organizationName || 'Spectra Operations' },
    });

    const user = await this.prisma.user.create({
      data: {
        organizationId: organization.id,
        email: dto.email,
        passwordHash,
        firstName: dto.firstName,
        lastName: dto.lastName,
        phone: dto.phone,
        role: 'ADMIN',
      },
      select: {
        id: true,
        organizationId: true,
        email: true,
        firstName: true,
        lastName: true,
        phone: true,
        role: true,
        isActive: true,
        createdAt: true,
      },
    });

    return user;
  }

  async createEmployee(dto: RegisterDto, admin: { organizationId: string }) {
    const existing = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });
    if (existing) {
      throw new ConflictException('Email address is already in use');
    }

    const passwordHash = await bcrypt.hash(dto.password, 10);
    return this.prisma.user.create({
      data: {
        organizationId: admin.organizationId,
        email: dto.email,
        passwordHash,
        firstName: dto.firstName,
        lastName: dto.lastName,
        phone: dto.phone,
        role: 'EMPLOYEE',
      },
      select: {
        id: true,
        organizationId: true,
        email: true,
        firstName: true,
        lastName: true,
        phone: true,
        role: true,
        isActive: true,
        createdAt: true,
      },
    });
  }

  private generateRefreshToken(): string {
    return crypto.randomBytes(48).toString('hex');
  }

  private hashToken(token: string): string {
    return crypto.createHash('sha256').update(token).digest('hex');
  }

  async login(dto: LoginDto): Promise<
    | { requiresTwoFactor: true; tfaToken: string }
    | {
        requiresTwoFactor: false;
        accessToken: string;
        refreshToken: string;
        user: {
          id: string;
          organizationId: string;
          email: string;
          firstName: string;
          lastName: string;
          role: string;
        };
      }
  > {
    const user = await this.prisma.user.findUnique({
      where: { email: dto.email },
    });

    if (!user || !user.isActive) {
      throw new UnauthorizedException('Invalid email or password');
    }

    const passwordValid = await bcrypt.compare(dto.password, user.passwordHash);
    if (!passwordValid) {
      throw new UnauthorizedException('Invalid email or password');
    }

    // If 2FA is enabled, hand back a short-lived token to complete step two.
    if (user.twoFactorEnabled) {
      const tfaToken = this.jwtService.sign(
        { sub: user.id, tfa: true, email: user.email },
        { expiresIn: '5m' },
      );
      return { requiresTwoFactor: true, tfaToken };
    }

    const session = await this.issueSession(user);
    return { requiresTwoFactor: false as const, ...session };
  }

  /** Complete a 2FA-gated login with a TOTP/backup code. */
  async completeTfaLogin(tfaToken: string, code: string) {
    let payload: any;
    try {
      payload = this.jwtService.verify(tfaToken);
    } catch {
      throw new UnauthorizedException(
        '2FA session expired — please sign in again',
      );
    }
    if (!payload?.tfa) {
      throw new UnauthorizedException('Invalid 2FA token');
    }

    const user = await this.prisma.user.findUnique({
      where: { id: payload.sub },
    });
    if (!user || !user.isActive) {
      throw new UnauthorizedException('Invalid email or password');
    }

    await this.tfa.verifyForLogin(user.id, code);
    return this.issueSession(user);
  }

  private async issueSession(user: {
    id: string;
    email: string;
    role: string;
    organizationId: string;
    firstName: string;
    lastName: string;
  }) {
    const payload = {
      sub: user.id,
      email: user.email,
      role: user.role,
      organizationId: user.organizationId,
    };
    const accessToken = this.jwtService.sign(payload);

    // Generate and store refresh token
    const rawToken = this.generateRefreshToken();
    const tokenHash = this.hashToken(rawToken);
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    await this.prisma.refreshToken.create({
      data: { userId: user.id, tokenHash, expiresAt },
    });

    return {
      accessToken,
      refreshToken: rawToken,
      user: {
        id: user.id,
        organizationId: user.organizationId,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        role: user.role,
      },
    };
  }

  async refresh(refreshToken: string) {
    if (!refreshToken) {
      throw new UnauthorizedException('Refresh token is required');
    }

    const tokenHash = this.hashToken(refreshToken);
    const stored = await this.prisma.refreshToken.findUnique({
      where: { tokenHash },
      include: { user: true },
    });

    if (!stored || stored.expiresAt < new Date() || !stored.user.isActive) {
      throw new UnauthorizedException('Invalid or expired refresh token');
    }

    // Rotate: delete old token, issue new one
    await this.prisma.refreshToken.delete({ where: { id: stored.id } });

    const payload = {
      sub: stored.user.id,
      email: stored.user.email,
      role: stored.user.role,
      organizationId: stored.user.organizationId,
    };
    const newAccessToken = this.jwtService.sign(payload);

    const newRawToken = this.generateRefreshToken();
    const newTokenHash = this.hashToken(newRawToken);
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    await this.prisma.refreshToken.create({
      data: { userId: stored.user.id, tokenHash: newTokenHash, expiresAt },
    });

    return {
      accessToken: newAccessToken,
      refreshToken: newRawToken,
      user: {
        id: stored.user.id,
        organizationId: stored.user.organizationId,
        email: stored.user.email,
        firstName: stored.user.firstName,
        lastName: stored.user.lastName,
        role: stored.user.role,
      },
    };
  }

  async logout(userId: string, refreshToken?: string) {
    if (refreshToken) {
      const tokenHash = this.hashToken(refreshToken);
      await this.prisma.refreshToken.deleteMany({ where: { tokenHash } });
    } else {
      // Delete ALL refresh tokens for this user (logout from all devices)
      await this.prisma.refreshToken.deleteMany({ where: { userId } });
    }
  }

  async updateProfile(
    userId: string,
    dto: {
      firstName?: string;
      lastName?: string;
      phone?: string;
      email?: string;
      photoUrl?: string;
    },
  ) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user) throw new UnauthorizedException('User not found');

    const data: any = {};
    if (dto.firstName) data.firstName = dto.firstName;
    if (dto.lastName) data.lastName = dto.lastName;
    if (dto.phone) data.phone = dto.phone;
    if (dto.photoUrl !== undefined) data.photoUrl = dto.photoUrl;
    if (dto.email) {
      const existing = await this.prisma.user.findUnique({
        where: { email: dto.email },
      });
      if (existing && existing.id !== userId) {
        throw new ConflictException('Email already in use');
      }
      data.email = dto.email;
    }

    return this.prisma.user.update({
      where: { id: userId },
      data,
      select: {
        id: true,
        email: true,
        firstName: true,
        lastName: true,
        phone: true,
        role: true,
      },
    });
  }

  async getMe(userId: string) {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: {
        id: true,
        organizationId: true,
        email: true,
        firstName: true,
        lastName: true,
        phone: true,
        photoUrl: true,
        role: true,
        isActive: true,
        createdAt: true,
        guardProfile: {
          select: {
            id: true,
            assignedSiteId: true,
            assignedSite: { select: { id: true, name: true } },
          },
        },
        clientProfile: { select: { id: true, companyName: true } },
      },
    });
    if (!user) {
      throw new UnauthorizedException(
        'User session details could not be found',
      );
    }
    return user;
  }
}

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  canActivate(context: ExecutionContext) {
    return super.canActivate(context);
  }

  handleRequest(err: any, user: any, info: any) {
    if (err || !user) {
      throw (
        err ||
        new UnauthorizedException('Authentication token is invalid or missing')
      );
    }
    return user;
  }
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from '../decorators/roles.decorator';

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector) {}

  private normalizeRole(role: string): 'ADMIN' | 'EMPLOYEE' | string {
    if (
      ['ADMIN', 'CEO', 'OPERATIONS_MANAGER', 'HR', 'SUPERVISOR'].includes(role)
    ) {
      return 'ADMIN';
    }
    if (['EMPLOYEE', 'GUARD'].includes(role)) {
      return 'EMPLOYEE';
    }
    return role;
  }

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(
      ROLES_KEY,
      [context.getHandler(), context.getClass()],
    );
    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }
    const { user } = context.switchToHttp().getRequest();
    if (!user || !user.role) {
      throw new ForbiddenException(
        'User session does not have access permissions',
      );
    }
    const normalizedUserRole = this.normalizeRole(user.role);
    const normalizedRequiredRoles = requiredRoles.map((role) =>
      this.normalizeRole(role),
    );
    const hasRole = normalizedRequiredRoles.includes(normalizedUserRole);
    if (!hasRole) {
      throw new ForbiddenException(
        `Access denied. Required roles: ${requiredRoles.join(', ')}`,
      );
    }
    return true;
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import type { Request } from 'express';
import { PrismaService } from '../../database/prisma.service';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy) {
  constructor(private prisma: PrismaService) {
    super({
      jwtFromRequest: ExtractJwt.fromExtractors([
        ExtractJwt.fromAuthHeaderAsBearerToken(),
        (req: Request) => req?.cookies?.access_token ?? null,
      ]),
      ignoreExpiration: false,
      secretOrKey: process.env.JWT_SECRET!,
    });
  }

  async validate(payload: {
    sub: string;
    email: string;
    role: string;
    organizationId: string;
  }) {
    const user = await this.prisma.user.findUnique({
      where: { id: payload.sub },
      select: {
        id: true,
        email: true,
        role: true,
        firstName: true,
        lastName: true,
        isActive: true,
        organizationId: true,
        guardProfile: { select: { id: true, assignedSiteId: true } },
        clientProfile: { select: { id: true } },
      },
    });

    if (!user || !user.isActive) {
      throw new UnauthorizedException('User account is inactive or not found');
    }

    return user;
  }
}

import {
  Injectable,
  UnauthorizedException,
  BadRequestException,
} from '@nestjs/common';
import { createHmac, randomBytes, createHash } from 'crypto';
import { PrismaService } from '../../database/prisma.service';

const BASE32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
const STEP_SECONDS = 30;
const WINDOW = 1; // ±1 step for clock drift

function base32Encode(buffer: Buffer): string {
  let bits = '';
  for (const byte of buffer) bits += byte.toString(2).padStart(8, '0');
  let out = '';
  for (let i = 0; i + 5 <= bits.length; i += 5) {
    out += BASE32_ALPHABET[parseInt(bits.slice(i, i + 5), 2)];
  }
  const rem = bits.length % 5;
  if (rem > 0)
    out +=
      BASE32_ALPHABET[
        parseInt(bits.slice(bits.length - rem).padEnd(5, '0'), 2)
      ];
  return out.replace(/=+$/, '');
}

function base32Decode(input: string): Buffer {
  const cleaned = input.toUpperCase().replace(/[^A-Z2-7]/g, '');
  let bits = '';
  for (const ch of cleaned) {
    const idx = BASE32_ALPHABET.indexOf(ch);
    if (idx === -1) throw new BadRequestException('Invalid base32 secret');
    bits += idx.toString(2).padStart(5, '0');
  }
  const bytes: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.slice(i, i + 8), 2));
  }
  return Buffer.from(bytes);
}

/** Generate the 6-digit TOTP code for a secret at a given time (RFC 6238). */
export function generateTOTP(secret: string, time = Date.now()): string {
  const counter = Math.floor(time / 1000 / STEP_SECONDS);
  const counterBuf = Buffer.alloc(8);
  counterBuf.writeBigUInt64BE(BigInt(counter));
  const hmac = createHmac('sha1', base32Decode(secret))
    .update(counterBuf)
    .digest();
  const offset = hmac[hmac.length - 1] & 0x0f;
  const code =
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff);
  return (code % 1_000_000).toString().padStart(6, '0');
}

/** Constant-time-ish code comparison. */
function codesEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

@Injectable()
export class TfaService {
  constructor(private prisma: PrismaService) {}

  /** Generate a new secret + otpauth URI for provisioning. */
  async startEnrollment(userId: string, email: string) {
    const secret = base32Encode(randomBytes(20));
    const uri = `otpauth://totp/BastionOS:${encodeURIComponent(email)}?secret=${secret}&issuer=BastionOS&algorithm=SHA1&digits=6&period=30`;

    // Persist pending secret (not yet active until verified)
    await this.prisma.user.update({
      where: { id: userId },
      data: { twoFactorSecret: secret },
    });

    return { secret, otpauthUri: uri };
  }

  /** Verify a code against a stored secret (with ±1 step drift window). */
  verifyCode(secret: string, code: string): boolean {
    if (!code || !/^\d{6}$/.test(code)) return false;
    const now = Date.now();
    for (let i = -WINDOW; i <= WINDOW; i++) {
      if (
        codesEqual(generateTOTP(secret, now + i * STEP_SECONDS * 1000), code)
      ) {
        return true;
      }
    }
    return false;
  }

  /** Confirm enrollment — turns the pending secret into an active one. */
  async confirmEnrollment(userId: string, code: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user?.twoFactorSecret)
      throw new BadRequestException('No pending 2FA enrollment');
    if (!this.verifyCode(user.twoFactorSecret, code)) {
      throw new BadRequestException('Invalid verification code');
    }
    const backupCodes = Array.from({ length: 8 }, () =>
      randomBytes(4).toString('hex').toUpperCase(),
    );

    await this.prisma.user.update({
      where: { id: userId },
      data: {
        twoFactorEnabled: true,
        twoFactorBackupCodes: JSON.stringify(
          backupCodes.map((c) => createHash('sha256').update(c).digest('hex')),
        ),
      },
    });

    // Return plaintext codes ONCE so the user can save them
    return { enabled: true, backupCodes };
  }

  /** Verify a backup code and consume it if valid. */
  private async consumeBackupCode(
    userId: string,
    code: string,
  ): Promise<boolean> {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user?.twoFactorBackupCodes) return false;
    const hashes: string[] = JSON.parse(user.twoFactorBackupCodes);
    const candidate = createHash('sha256')
      .update(code.trim().toUpperCase())
      .digest('hex');
    const idx = hashes.indexOf(candidate);
    if (idx === -1) return false;
    hashes.splice(idx, 1);
    await this.prisma.user.update({
      where: { id: userId },
      data: { twoFactorBackupCodes: JSON.stringify(hashes) },
    });
    return true;
  }

  /**
   * Verify a login attempt's 2FA code. Returns true if the code (or a valid
   * backup code) was accepted.
   */
  async verifyForLogin(userId: string, code: string): Promise<boolean> {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user?.twoFactorEnabled) return true; // 2FA not enabled — nothing to verify
    if (
      user.twoFactorSecret &&
      this.verifyCode(user.twoFactorSecret, code.trim())
    )
      return true;
    if (await this.consumeBackupCode(userId, code.trim())) return true;
    throw new UnauthorizedException('Invalid two-factor authentication code');
  }

  async disable(userId: string, code: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user?.twoFactorEnabled)
      throw new BadRequestException('2FA is not enabled');
    if (
      user.twoFactorSecret &&
      this.verifyCode(user.twoFactorSecret, code.trim())
    ) {
      await this.prisma.user.update({
        where: { id: userId },
        data: {
          twoFactorEnabled: false,
          twoFactorSecret: null,
          twoFactorBackupCodes: null,
        },
      });
      return { disabled: true };
    }
    throw new UnauthorizedException('Invalid two-factor authentication code');
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { CreateClientDto, UpdateClientDto } from './dto/client.dto';

@Injectable()
export class ClientService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: {
    page?: number;
    limit?: number;
    search?: string;
    billingStatus?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 10;
    const skip = (page - 1) * limit;

    const where: any = { organizationId: query.organizationId };
    if (query.billingStatus) where.billingStatus = query.billingStatus;
    if (query.search) {
      where.OR = [
        { companyName: { contains: query.search, mode: 'insensitive' } },
        { estateName: { contains: query.search, mode: 'insensitive' } },
        { contactPerson: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    const [data, total] = await Promise.all([
      this.prisma.client.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: { sites: { select: { id: true, name: true } } },
      }),
      this.prisma.client.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }

  async findOne(id: string, organizationId?: string) {
    const where: any = { id };
    if (organizationId) where.organizationId = organizationId;
    const client = await this.prisma.client.findFirst({
      where,
      include: { sites: true },
    });
    if (!client) throw new NotFoundException('Client not found');
    return client;
  }

  /** Full data bundle for a client — sites, incidents and attendance summary. */
  async exportData(id: string, organizationId?: string) {
    const client = await this.findOne(id, organizationId);
    const sites = await this.prisma.site.findMany({
      where: { clientId: id },
      include: {
        _count: { select: { guards: true, incidents: true } },
        incidents: {
          orderBy: { reportedAt: 'desc' },
          take: 50,
          select: {
            id: true,
            title: true,
            incidentType: true,
            severity: true,
            status: true,
            reportedAt: true,
            description: true,
          },
        },
      },
    });
    const attendance = await this.prisma.attendance.findMany({
      where: { site: { clientId: id } },
      orderBy: { createdAt: 'desc' },
      take: 100,
      select: {
        id: true,
        status: true,
        isLate: true,
        checkInTime: true,
        checkOutTime: true,
        guard: { select: { fullName: true } },
        site: { select: { name: true } },
      },
    });

    return {
      exportedAt: new Date().toISOString(),
      client: {
        id: client.id,
        companyName: client.companyName,
        estateName: client.estateName,
        contactPerson: client.contactPerson,
        phone: client.phone,
        email: client.email,
        contractStart: client.contractStart,
        contractEnd: client.contractEnd,
        monthlyFee: client.monthlyFee,
        numberOfGuardsAllocated: client.numberOfGuardsAllocated,
        billingStatus: client.billingStatus,
      },
      sites,
      recentAttendance: attendance,
    };
  }

  async create(dto: CreateClientDto, organizationId: string) {
    return this.prisma.client.create({
      data: {
        organizationId,
        companyName: dto.companyName,
        estateName: dto.estateName,
        contactPerson: dto.contactPerson,
        phone: dto.phone,
        email: dto.email,
        contractStart: new Date(dto.contractStart),
        contractEnd: new Date(dto.contractEnd),
        monthlyFee: dto.monthlyFee,
        numberOfGuardsAllocated: dto.numberOfGuardsAllocated,
        assignedSupervisorId: dto.assignedSupervisorId,
        billingStatus: dto.billingStatus,
        notes: dto.notes,
      },
    });
  }

  async update(id: string, dto: UpdateClientDto, organizationId: string) {
    await this.findOne(id, organizationId);
    const data: any = { ...dto };
    if (dto.contractEnd) data.contractEnd = new Date(dto.contractEnd);
    return this.prisma.client.update({ where: { id }, data });
  }

  async remove(id: string, organizationId: string, userId?: string) {
    await this.findOne(id, organizationId);
    const result = await this.prisma.$transaction(async (tx) => {
      // Find all sites belonging to this client
      const sites = await tx.site.findMany({ where: { clientId: id } });
      const siteIds = sites.map((s) => s.id);

      if (siteIds.length > 0) {
        // Unlink guards from these sites
        await tx.guard.updateMany({
          where: { assignedSiteId: { in: siteIds } },
          data: { assignedSiteId: null },
        });
        // Delete attendance records, patrol routes, incidents for these sites
        await tx.attendance.deleteMany({
          where: { siteId: { in: siteIds } },
        });
        await tx.patrolLog.deleteMany({
          where: { patrolRoute: { siteId: { in: siteIds } } },
        });
        await tx.patrolRecord.deleteMany({
          where: { route: { siteId: { in: siteIds } } },
        });
        await tx.patrolCheckpoint.deleteMany({
          where: { patrolRoute: { siteId: { in: siteIds } } },
        });
        await tx.patrolRoute.deleteMany({
          where: { siteId: { in: siteIds } },
        });
        await tx.incident.deleteMany({
          where: { siteId: { in: siteIds } },
        });
        // Delete the sites
        await tx.site.deleteMany({ where: { id: { in: siteIds } } });
      }

      // Delete the client
      return tx.client.delete({ where: { id } });
    });

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: userId || '',
          action: 'CLIENT_DELETED',
          entity: 'Client',
          entityId: id,
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return result;
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

@Injectable()
export class DashboardService {
  constructor(private prisma: PrismaService) {}

  async getStats(organizationId: string) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const [
      totalGuards,
      activeGuards,
      onLeaveGuards,
      suspendedGuards,
      totalSites,
      highRiskSites,
      totalClients,
      openIncidents,
      todayAttendance,
      todayLate,
      todayAbsent,
      todayFlagged,
      totalPatrols,
      completedPatrols,
      inProgressPatrols,
    ] = await Promise.all([
      this.prisma.guard.count({ where: { organizationId } }),
      this.prisma.guard.count({ where: { organizationId, status: 'ACTIVE' } }),
      this.prisma.guard.count({
        where: { organizationId, status: 'ON_LEAVE' },
      }),
      this.prisma.guard.count({
        where: { organizationId, status: 'SUSPENDED' },
      }),
      this.prisma.site.count({ where: { organizationId } }),
      this.prisma.site.count({
        where: { organizationId, riskLevel: { in: ['HIGH', 'CRITICAL'] } },
      }),
      this.prisma.client.count({ where: { organizationId } }),
      this.prisma.incident.count({
        where: {
          site: { organizationId },
          investigationStatus: { in: ['OPEN', 'UNDER_INVESTIGATION'] },
        },
      }),
      this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: today, lt: tomorrow },
          status: { not: 'ABSENT' },
        },
      }),
      this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: today, lt: tomorrow },
          isLate: true,
        },
      }),
      this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: today, lt: tomorrow },
          status: 'ABSENT',
        },
      }),
      this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: today, lt: tomorrow },
          status: 'FLAGGED',
        },
      }),
      this.prisma.patrolRecord.count({
        where: { route: { site: { organizationId } } },
      }),
      this.prisma.patrolRecord.count({
        where: { route: { site: { organizationId } }, status: 'COMPLETED' },
      }),
      this.prisma.patrolRecord.count({
        where: { route: { site: { organizationId } }, status: 'IN_PROGRESS' },
      }),
    ]);

    // Attendance rate: (non-absent active guards) / total active guards
    const attendanceRate =
      activeGuards > 0
        ? Math.round(((activeGuards - todayAbsent) / activeGuards) * 1000) / 10
        : 100;

    return {
      totalGuards,
      activeGuards,
      onLeaveGuards,
      suspendedGuards,
      totalSites,
      highRiskSites,
      totalClients,
      openIncidents,
      todayAttendance,
      todayLate,
      todayAbsent,
      todayFlagged,
      attendanceRate,
      totalPatrols,
      completedPatrols,
      inProgressPatrols,
    };
  }

  async getIncidentsByType(organizationId: string) {
    const incidents = await this.prisma.incident.groupBy({
      by: ['incidentType'],
      where: { site: { organizationId } },
      _count: { id: true },
    });
    return incidents.map((i) => ({ type: i.incidentType, count: i._count.id }));
  }

  async getSiteRiskDistribution(organizationId: string) {
    const sites = await this.prisma.site.groupBy({
      by: ['riskLevel'],
      where: { organizationId },
      _count: { id: true },
    });
    return sites.map((s) => ({ riskLevel: s.riskLevel, count: s._count.id }));
  }

  async getPatrolStats(organizationId: string) {
    const total = await this.prisma.patrolRecord.count({
      where: { route: { site: { organizationId } } },
    });
    const completed = await this.prisma.patrolRecord.count({
      where: { route: { site: { organizationId } }, status: 'COMPLETED' },
    });
    return {
      total,
      completed,
      rate: total > 0 ? Math.round((completed / total) * 100) : 100,
    };
  }

  async getAttendanceTrend(organizationId: string) {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      date.setHours(0, 0, 0, 0);
      const nextDate = new Date(date);
      nextDate.setDate(nextDate.getDate() + 1);

      const total = await this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: date, lt: nextDate },
        },
      });
      const late = await this.prisma.attendance.count({
        where: {
          guard: { organizationId },
          checkInTime: { gte: date, lt: nextDate },
          isLate: true,
        },
      });

      const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
      days.push({
        day: dayNames[date.getDay()],
        rate: total > 0 ? Math.round(((total - late) / total) * 100) : 100,
      });
    }
    return days;
  }

  async getRecentActivities(organizationId: string) {
    const [recentIncidents, recentAttendance, recentPatrols] =
      await Promise.all([
        this.prisma.incident.findMany({
          where: { site: { organizationId } },
          take: 5,
          orderBy: { createdAt: 'desc' },
          select: {
            incidentType: true,
            severity: true,
            site: { select: { name: true } },
            createdAt: true,
          },
        }),
        this.prisma.attendance.findMany({
          where: { guard: { organizationId } },
          take: 5,
          orderBy: { checkInTime: 'desc' },
          select: {
            guard: { select: { fullName: true } },
            site: { select: { name: true } },
            checkInTime: true,
            isLate: true,
          },
        }),
        this.prisma.patrolRecord.findMany({
          where: { route: { site: { organizationId } } },
          take: 5,
          orderBy: { startTime: 'desc' },
          select: {
            guard: { select: { fullName: true } },
            route: { select: { name: true, site: { select: { name: true } } } },
            status: true,
            startTime: true,
            completionPercentage: true,
          },
        }),
      ]);

    const activities: { type: string; text: string; time: Date }[] = [];

    for (const inc of recentIncidents) {
      activities.push({
        type: 'incident',
        text: `Incident reported: ${inc.incidentType} at ${inc.site?.name || 'unknown site'}`,
        time: inc.createdAt,
      });
    }
    for (const att of recentAttendance) {
      activities.push({
        type: att.isLate ? 'late' : 'attendance',
        text: `Guard ${att.guard.fullName} checked in at ${att.site.name}`,
        time: att.checkInTime,
      });
    }
    for (const patrol of recentPatrols) {
      activities.push({
        type:
          patrol.status === 'COMPLETED' ? 'patrol_completed' : 'patrol_started',
        text: `Guard ${patrol.guard.fullName} ${patrol.status === 'COMPLETED' ? 'completed' : 'started'} patrol "${patrol.route.name}" at ${patrol.route.site.name} (${patrol.completionPercentage}%)`,
        time: patrol.startTime,
      });
    }

    activities.sort((a, b) => b.time.getTime() - a.time.getTime());
    return activities.slice(0, 10);
  }

  async getGuardStats(organizationId: string) {
    const guards = await this.prisma.guard.findMany({
      where: { organizationId },
      select: {
        id: true,
        fullName: true,
        status: true,
        currentShift: true,
        performanceScore: true,
        assignedSite: { select: { name: true } },
        _count: {
          select: {
            attendances: true,
            patrolRecords: true,
          },
        },
      },
    });

    return guards.map((g) => ({
      id: g.id,
      name: g.fullName,
      status: g.status,
      shift: g.currentShift,
      performanceScore: g.performanceScore,
      site: g.assignedSite?.name || 'Unassigned',
      totalAttendances: g._count.attendances,
      totalPatrols: g._count.patrolRecords,
    }));
  }

  async getSiteComparison(organizationId: string) {
    const sites = await this.prisma.site.findMany({
      where: { organizationId },
      include: {
        _count: {
          select: { guards: true, incidents: true, attendances: true },
        },
        client: { select: { companyName: true } },
      },
    });

    return sites.map((s) => ({
      id: s.id,
      name: s.name,
      client: s.client.companyName,
      riskLevel: s.riskLevel,
      targetGuards: s.targetGuards,
      assignedGuards: s._count.guards,
      totalIncidents: s._count.incidents,
      totalAttendances: s._count.attendances,
      guardFillRate:
        s.targetGuards > 0
          ? Math.round((s._count.guards / s.targetGuards) * 100)
          : 0,
    }));
  }

  /**
   * Everything the live map needs in one request: sites with coordinates,
   * on-duty guards with their latest known position (from their most recent
   * GPS check-in), and recent incidents with severity + location.
   */
  async getMapData(organizationId: string) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [sites, activeGuards, recentIncidents] = await Promise.all([
      this.prisma.site.findMany({
        where: { organizationId },
        select: {
          id: true,
          name: true,
          address: true,
          latitude: true,
          longitude: true,
          riskLevel: true,
          targetGuards: true,
          client: { select: { companyName: true } },
          _count: { select: { guards: true, incidents: true } },
          incidents: {
            where: {
              investigationStatus: { in: ['OPEN', 'UNDER_INVESTIGATION'] },
            },
            select: { id: true },
          },
        },
      }),
      // ACTIVE guards with their latest attendance (for last-known position)
      this.prisma.guard.findMany({
        where: { organizationId, status: 'ACTIVE' },
        select: {
          id: true,
          fullName: true,
          currentShift: true,
          assignedSiteId: true,
          assignedSite: {
            select: { id: true, name: true, latitude: true, longitude: true },
          },
          attendances: {
            orderBy: { checkInTime: 'desc' },
            take: 1,
            select: {
              checkInTime: true,
              checkInLatitude: true,
              checkInLongitude: true,
              checkOutTime: true,
              status: true,
            },
          },
        },
      }),
      this.prisma.incident.findMany({
        // Active incidents always show; closed ones drop off after 14 days
        where: {
          site: { organizationId },
          OR: [
            { investigationStatus: { in: ['OPEN', 'UNDER_INVESTIGATION'] } },
            { reportedAt: { gte: this.startOfDaysAgo(14) } },
          ],
        },
        orderBy: { reportedAt: 'desc' },
        take: 50,
        select: {
          id: true,
          title: true,
          severity: true,
          status: true,
          reportedAt: true,
          siteId: true,
          site: { select: { name: true, latitude: true, longitude: true } },
        },
      }),
    ]);

    const siteMap = new Map(sites.map((s) => [s.id, s]));

    const guards = activeGuards.map((g) => {
      const latest = g.attendances[0];
      const onDuty = latest && !latest.checkOutTime;
      const hasGps =
        typeof latest?.checkInLatitude === 'number' &&
        typeof latest?.checkInLongitude === 'number' &&
        latest.checkInLatitude !== 0 &&
        latest.checkInLongitude !== 0;
      const site = g.assignedSite;

      return {
        id: g.id,
        fullName: g.fullName,
        shift: g.currentShift,
        onDuty,
        status: latest?.status ?? null,
        lastSeen: latest?.checkInTime?.toISOString() ?? null,
        // Prefer real GPS from the last check-in; fall back to the site location
        latitude: hasGps ? latest.checkInLatitude : (site?.latitude ?? null),
        longitude: hasGps ? latest.checkInLongitude : (site?.longitude ?? null),
        siteId: site?.id ?? g.assignedSiteId ?? null,
        siteName: site?.name ?? null,
      };
    });

    const incidents = recentIncidents.map((i) => ({
      id: i.id,
      title: i.title,
      severity: i.severity,
      status: i.status,
      reportedAt: i.reportedAt.toISOString(),
      siteId: i.siteId,
      siteName: i.site?.name ?? null,
      latitude: i.site?.latitude ?? null,
      longitude: i.site?.longitude ?? null,
    }));

    const siteList = sites.map((s) => ({
      id: s.id,
      name: s.name,
      address: s.address,
      latitude: s.latitude,
      longitude: s.longitude,
      riskLevel: s.riskLevel,
      clientName: s.client?.companyName ?? null,
      guardsAssigned: s._count.guards,
      guardsOnDuty: guards.filter((g) => g.siteId === s.id && g.onDuty).length,
      totalIncidents: s._count.incidents,
      openIncidents: s.incidents.length,
      targetGuards: s.targetGuards,
    }));

    return {
      generatedAt: new Date().toISOString(),
      bounds: this.computeBounds(siteList),
      sites: siteList,
      guards,
      incidents,
    };
  }

  private startOfDaysAgo(days: number): Date {
    const d = new Date();
    d.setDate(d.getDate() - days);
    d.setHours(0, 0, 0, 0);
    return d;
  }

  private computeBounds(sites: { latitude: number; longitude: number }[]) {
    const withCoords = sites.filter(
      (s) => typeof s.latitude === 'number' && typeof s.longitude === 'number',
    );
    if (withCoords.length === 0) return null;
    const lats = withCoords.map((s) => s.latitude);
    const lngs = withCoords.map((s) => s.longitude);
    return {
      north: Math.max(...lats),
      south: Math.min(...lats),
      east: Math.max(...lngs),
      west: Math.min(...lngs),
    };
  }
}

