import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import * as bcrypt from 'bcrypt';
import { PrismaService } from '../../database/prisma.service';
import {
  CreateGuardDto,
  UpdateGuardDto,
  TransferGuardDto,
} from './dto/guard.dto';

// Header aliases accepted in import CSVs (case-insensitive)
const FIELD_ALIASES: Record<string, string> = {
  'full name': 'fullName',
  name: 'fullName',
  'employee name': 'fullName',
  nin: 'nin',
  'national id': 'nin',
  phone: 'phone',
  'phone number': 'phone',
  mobile: 'phone',
  address: 'address',
  'emergency contact': 'emergencyContact',
  'next of kin': 'emergencyContact',
  bvn: 'bvn',
  'guarantor details': 'guarantorDetails',
  guarantor: 'guarantorDetails',
  'employment date': 'employmentDate',
  'start date': 'employmentDate',
  'date joined': 'employmentDate',
  status: 'status',
  shift: 'currentShift',
  'current shift': 'currentShift',
  site: 'siteName',
  'site name': 'siteName',
  'assigned site': 'siteName',
  email: 'email',
  password: 'password',
};

/** Minimal RFC-4180-ish CSV parser (quotes, escaped quotes, CRLF). */
function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      row.push(field);
      field = '';
    } else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && text[i + 1] === '\n') i++;
      row.push(field);
      field = '';
      if (row.some((f) => f.trim() !== '')) rows.push(row);
      row = [];
    } else {
      field += ch;
    }
  }
  if (field !== '' || row.length > 0) {
    row.push(field);
    if (row.some((f) => f.trim() !== '')) rows.push(row);
  }
  return rows;
}

/** Map a CSV header row to canonical field names. */
function mapHeaders(headers: string[]): string[] {
  return headers.map((h) => {
    const key = h.trim().toLowerCase().replace(/\s+/g, ' ');
    return FIELD_ALIASES[key] ?? key.replace(/[^a-z0-9]/g, '');
  });
}

@Injectable()
export class GuardService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: {
    page?: number;
    limit?: number;
    status?: string;
    siteId?: string;
    search?: string;
    sortBy?: string;
    sortOrder?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 10;
    const skip = (page - 1) * limit;

    const where: any = { organizationId: query.organizationId };
    if (query.status) where.status = query.status;
    if (query.siteId) where.assignedSiteId = query.siteId;
    if (query.search) {
      where.OR = [
        { fullName: { contains: query.search, mode: 'insensitive' } },
        { nin: { contains: query.search, mode: 'insensitive' } },
        { phone: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    const orderBy: any = {};
    if (query.sortBy) {
      orderBy[query.sortBy] = query.sortOrder || 'asc';
    } else {
      orderBy.createdAt = 'desc';
    }

    const [data, total] = await Promise.all([
      this.prisma.guard.findMany({
        where,
        skip,
        take: limit,
        orderBy,
        include: { assignedSite: { select: { id: true, name: true } } },
      }),
      this.prisma.guard.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }

  /**
   * Compute a performance score per guard from attendance, patrol and
   * incident data, persist it, and return the ranked list.
   */
  async getPerformance(organizationId: string) {
    const guards = await this.prisma.guard.findMany({
      where: { organizationId },
      select: {
        id: true,
        fullName: true,
        status: true,
        performanceScore: true,
        assignedSite: { select: { name: true } },
        _count: {
          select: { attendances: true, patrolRecords: true },
        },
        attendances: {
          select: { isLate: true },
        },
        patrolRecords: {
          select: { completionPercentage: true },
        },
      },
    });

    const scored = guards.map((g) => {
      const late = g.attendances.filter((a) => a.isLate).length;
      const totalAtt = g.attendances.length;
      const attRate =
        totalAtt > 0 ? Math.round(((totalAtt - late) / totalAtt) * 100) : 100;
      const avgCompletion =
        g.patrolRecords.length > 0
          ? Math.round(
              g.patrolRecords.reduce((s, p) => s + p.completionPercentage, 0) /
                g.patrolRecords.length,
            )
          : 100;
      const score = Math.max(
        40,
        Math.min(99, Math.round(attRate * 0.5 + avgCompletion * 0.5)),
      );

      return {
        id: g.id,
        fullName: g.fullName,
        status: g.status,
        site: g.assignedSite?.name ?? '—',
        attendanceRate: attRate,
        patrolCompletion: avgCompletion,
        lateCheckIns: late,
        score,
      };
    });

    scored.sort((a, b) => b.score - a.score);

    // Persist the computed scores
    for (const item of scored) {
      if (item.score !== 100) {
        await this.prisma.guard.update({
          where: { id: item.id },
          data: { performanceScore: item.score },
        });
      }
    }

    return scored;
  }

  async findOne(id: string, organizationId?: string) {
    const where: any = { id };
    if (organizationId) where.organizationId = organizationId;
    const guard = await this.prisma.guard.findFirst({
      where,
      include: {
        assignedSite: true,
        assignedSupervisor: {
          select: { id: true, firstName: true, lastName: true },
        },
        attendances: {
          take: 10,
          orderBy: { createdAt: 'desc' },
          include: { site: { select: { name: true } } },
        },
      },
    });
    if (!guard) throw new NotFoundException('Guard not found');
    return guard;
  }

  async create(dto: CreateGuardDto, organizationId: string) {
    return this.prisma.guard.create({
      data: {
        organizationId,
        fullName: dto.fullName,
        photoUrl: dto.photoUrl || '',
        phone: dto.phone,
        address: dto.address,
        emergencyContact: dto.emergencyContact,
        nin: dto.nin,
        bvn: dto.bvn,
        guarantorDetails: dto.guarantorDetails,
        employmentDate: new Date(dto.employmentDate),
        status: dto.status,
        currentShift: dto.currentShift,
        assignedSiteId: dto.assignedSiteId,
        assignedSupervisorId: dto.assignedSupervisorId,
        trainingRecords: dto.trainingRecords || '[]',
        certificates: dto.certificates || '[]',
        backgroundVerification:
          dto.backgroundVerification || '{"status":"PENDING"}',
        disciplinaryHistory: dto.disciplinaryHistory || '[]',
      },
    });
  }

  async update(id: string, dto: UpdateGuardDto, organizationId: string) {
    await this.findOne(id, organizationId);
    return this.prisma.guard.update({ where: { id }, data: dto as any });
  }

  async transfer(id: string, dto: TransferGuardDto, organizationId: string) {
    await this.findOne(id, organizationId);
    return this.prisma.guard.update({
      where: { id },
      data: {
        assignedSiteId: dto.newSiteId,
        assignedSupervisorId: dto.newSupervisorId,
      },
    });
  }

  async remove(id: string, organizationId: string, userId?: string) {
    await this.findOne(id, organizationId);
    const result = await this.prisma.$transaction(async (tx) => {
      // Delete attendance records
      await tx.attendance.deleteMany({ where: { guardId: id } });
      // Delete patrol records
      await tx.patrolRecord.deleteMany({ where: { guardId: id } });
      // Delete patrol logs
      await tx.patrolLog.deleteMany({ where: { guardId: id } });
      // Unlink guard from patrol routes
      await tx.patrolRoute.updateMany({
        where: { assignedGuardId: id },
        data: { assignedGuardId: null },
      });
      // Delete the guard
      return tx.guard.delete({ where: { id } });
    });

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: userId || '',
          action: 'GUARD_DELETED',
          entity: 'Guard',
          entityId: id,
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return result;
  }

  async bulkAssign(
    dto: { siteId: string; guardIds: string[] },
    organizationId: string,
  ) {
    const site = await this.prisma.site.findFirst({
      where: { id: dto.siteId, organizationId },
    });
    if (!site) throw new NotFoundException('Site not found');

    await this.prisma.guard.updateMany({
      where: { id: { in: dto.guardIds }, organizationId },
      data: { assignedSiteId: dto.siteId },
    });

    return {
      message: `${dto.guardIds.length} guards assigned to ${site.name}`,
    };
  }

  async updateVerification(
    id: string,
    dto: { status: string; verifiedBy?: string; date?: string },
    organizationId: string,
  ) {
    await this.findOne(id, organizationId);
    const existing = JSON.parse(
      (
        await this.prisma.guard.findUnique({
          where: { id },
          select: { backgroundVerification: true },
        })
      )?.backgroundVerification || '{}',
    );
    const updated = {
      ...existing,
      status: dto.status,
      verifiedBy: dto.verifiedBy || existing.verifiedBy || '',
      date: dto.date || new Date().toISOString(),
    };
    return this.prisma.guard.update({
      where: { id },
      data: { backgroundVerification: JSON.stringify(updated) },
    });
  }

  async findUnassigned(organizationId: string) {
    return this.prisma.guard.findMany({
      where: { organizationId, assignedSiteId: null, status: 'ACTIVE' },
      select: { id: true, fullName: true, currentShift: true },
    });
  }

  async findWithAttendanceStats(date: string, organizationId: string) {
    const startOfDay = new Date(date);
    startOfDay.setHours(0, 0, 0, 0);
    const endOfDay = new Date(date);
    endOfDay.setHours(23, 59, 59, 999);

    const guards = await this.prisma.guard.findMany({
      where: { organizationId },
      include: {
        assignedSite: { select: { id: true, name: true } },
        attendances: {
          where: { checkInTime: { gte: startOfDay, lte: endOfDay } },
          take: 1,
          orderBy: { checkInTime: 'desc' },
        },
      },
    });

    return guards.map((g) => ({
      id: g.id,
      fullName: g.fullName,
      status: g.status,
      currentShift: g.currentShift,
      siteName: g.assignedSite?.name || null,
      checkedIn: g.attendances.length > 0,
      checkInTime: g.attendances[0]?.checkInTime || null,
      checkInStatus: g.attendances[0]?.status || null,
    }));
  }

  async getStats(organizationId: string) {
    const [total, active, onLeave, suspended] = await Promise.all([
      this.prisma.guard.count({ where: { organizationId } }),
      this.prisma.guard.count({ where: { organizationId, status: 'ACTIVE' } }),
      this.prisma.guard.count({
        where: { organizationId, status: 'ON_LEAVE' },
      }),
      this.prisma.guard.count({
        where: { organizationId, status: 'SUSPENDED' },
      }),
    ]);
    return {
      total,
      active,
      onLeave,
      suspended,
      inactive: total - active - onLeave - suspended,
    };
  }

  // ── Bulk import ────────────────────────────────────────────────────────────

  /**
   * Bulk-create (or upsert) guards from an array of row objects. Optionally
   * creates login accounts (role GUARD) so imported personnel can use the
   * mobile app immediately. Returns a per-row result report.
   */
  async importGuards(opts: {
    rows: Record<string, any>[];
    createAccounts?: boolean;
    mode?: 'create' | 'upsert';
    organizationId: string;
  }) {
    const { rows, organizationId } = opts;
    const mode = opts.mode ?? 'create';
    const createAccounts = opts.createAccounts ?? false;
    const maxErrors = 200;

    const errors: { row: number; reason: string }[] = [];
    const createdAccounts: { email: string; password: string }[] = [];
    let created = 0;
    let updated = 0;
    let skipped = 0;

    // Cache sites by name for friendly siteName resolution
    const sites = await this.prisma.site.findMany({
      where: { organizationId },
      select: { id: true, name: true },
    });
    const siteByName = new Map(
      sites.map((s) => [s.name.toLowerCase().trim(), s.id]),
    );

    const pushError = (row: number, reason: string) => {
      if (errors.length < maxErrors) errors.push({ row, reason });
    };

    for (let i = 0; i < rows.length; i++) {
      const raw = rows[i] ?? {};
      const rowNo = i + 2; // 1-based data row (header is row 1)

      try {
        const fullName = String(raw.fullName ?? '').trim();
        const nin = String(raw.nin ?? '').trim();
        const phone = String(raw.phone ?? '').trim();
        const email = String(raw.email ?? '')
          .trim()
          .toLowerCase();

        if (!fullName || !nin || !phone) {
          pushError(rowNo, 'fullName, nin and phone are required');
          skipped++;
          continue;
        }

        // Resolve site by name or id
        let siteId: string | undefined = raw.siteId || undefined;
        const siteName = String(raw.siteName ?? '').trim();
        if (!siteId && siteName) {
          siteId = siteByName.get(siteName.toLowerCase());
          if (!siteId) {
            pushError(rowNo, `Unknown site "${siteName}"`);
            skipped++;
            continue;
          }
        }
        if (siteId) {
          const site = await this.prisma.site.findFirst({
            where: { id: siteId, organizationId },
            select: { id: true },
          });
          if (!site) {
            pushError(rowNo, `Site not found in your organization`);
            skipped++;
            continue;
          }
        }

        const status = ['ACTIVE', 'INACTIVE', 'SUSPENDED', 'ON_LEAVE'].includes(
          String(raw.status ?? '').toUpperCase(),
        )
          ? String(raw.status).toUpperCase()
          : 'ACTIVE';
        const shift = ['DAY', 'NIGHT', 'OFF'].includes(
          String(raw.currentShift ?? '').toUpperCase(),
        )
          ? String(raw.currentShift).toUpperCase()
          : 'DAY';
        const employmentDate = raw.employmentDate
          ? new Date(String(raw.employmentDate))
          : new Date();
        if (Number.isNaN(employmentDate.getTime())) {
          pushError(rowNo, `Invalid employment date "${raw.employmentDate}"`);
          skipped++;
          continue;
        }

        const data = {
          fullName,
          phone,
          address: String(raw.address ?? '').trim() || 'Not provided',
          emergencyContact:
            String(raw.emergencyContact ?? '').trim() || 'Not provided',
          nin,
          bvn: String(raw.bvn ?? '').trim() || undefined,
          guarantorDetails:
            String(raw.guarantorDetails ?? '').trim() || 'Not provided',
          employmentDate,
          status,
          currentShift: shift,
          assignedSiteId: siteId ?? null,
          trainingRecords: '[]',
          certificates: '[]',
          backgroundVerification: '{"status":"PENDING"}',
          disciplinaryHistory: '[]',
        };

        const existing = await this.prisma.guard.findFirst({
          where: { organizationId, OR: [{ nin }, { phone }] },
          select: { id: true },
        });

        let guardId: string;
        if (existing && mode === 'upsert') {
          await this.prisma.guard.update({ where: { id: existing.id }, data });
          guardId = existing.id;
          updated++;
        } else if (existing) {
          skipped++;
          continue;
        } else {
          const guard = await this.prisma.guard.create({
            data: { ...data, organizationId },
          });
          guardId = guard.id;
          created++;
        }

        // Optionally create a login account and link it to the guard
        if (createAccounts && email) {
          const used = await this.prisma.user.findUnique({ where: { email } });
          if (used) {
            pushError(rowNo, `Email ${email} already in use — account skipped`);
          } else {
            const password =
              String(raw.password ?? '').trim() || `Bastion@${nin.slice(-4)}`;
            const firstName = fullName.split(' ')[0] || 'Guard';
            const lastName =
              fullName.split(' ').slice(1).join(' ') || 'Personnel';
            const passwordHash = await bcrypt.hash(password, 10);
            const user = await this.prisma.user.create({
              data: {
                organizationId,
                email,
                passwordHash,
                firstName,
                lastName,
                phone,
                role: 'GUARD',
              },
            });
            await this.prisma.guard.update({
              where: { id: guardId },
              data: { userId: user.id },
            });
            createdAccounts.push({ email, password });
          }
        }
      } catch (err) {
        pushError(rowNo, String((err as Error).message).slice(0, 160));
        skipped++;
      }
    }

    return {
      total: rows.length,
      created,
      updated,
      skipped,
      accountsCreated: createdAccounts.length,
      createdAccounts,
      errors,
      errorsTruncated: errors.length >= maxErrors,
    };
  }

  /** Parse a CSV upload into row objects, mapping headers to canonical names. */
  importFromCsv(text: string, organizationId: string) {
    const table = parseCsv(text);
    if (table.length < 2) {
      throw new BadRequestException(
        'CSV must contain a header row and at least one data row',
      );
    }
    const headers = mapHeaders(table[0]);
    if (
      !headers.includes('fullName') ||
      !headers.includes('nin') ||
      !headers.includes('phone')
    ) {
      throw new BadRequestException(
        'CSV must include "Full Name", "NIN" and "Phone" columns (see the template)',
      );
    }
    const rows = table.slice(1).map((cells) => {
      const row: Record<string, any> = {};
      cells.forEach((value, idx) => {
        const key = headers[idx];
        if (key) row[key] = value.trim();
      });
      return row;
    });
    return rows;
  }

  /** Build a downloadable CSV template with example rows. */
  buildCsvTemplate(): string {
    const header = [
      'Full Name',
      'NIN',
      'Phone',
      'Address',
      'Emergency Contact',
      'BVN',
      'Guarantor Details',
      'Employment Date',
      'Status',
      'Shift',
      'Site Name',
      'Email',
      'Password',
    ];
    const example = [
      'John Okafor',
      '12345678901',
      '08031234567',
      '12 Marina Road, Lagos',
      'Mary Okafor - 08039876543',
      '22334455667',
      'Brother - 08030000001',
      '2026-01-15',
      'ACTIVE',
      'NIGHT',
      'Banana Island Alpha Zone',
      'john.okafor@example.com',
      'Bastion@0001',
    ];
    const escape = (v: string) =>
      /[,"\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v;
    return [header.map(escape).join(','), example.map(escape).join(',')].join(
      '\r\n',
    );
  }
}

import { Test } from '@nestjs/testing';
import {
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { IncidentService } from './incident.service';
import { PrismaService } from '../../database/prisma.service';
import { NotificationsService } from '../notifications/notifications.service';
import { RealtimeService } from '../realtime/realtime.service';

function dateKey(date: Date): string {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

function todayKey(): string {
  return dateKey(new Date());
}

function daysAgo(days: number): Date {
  const d = new Date();
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() - days);
  return d;
}

describe('IncidentService', () => {
  let service: IncidentService;
  let prismaMock: {
    incident: { count: jest.Mock; groupBy: jest.Mock };
  };

  const organizationId = 'org-1';

  beforeEach(async () => {
    prismaMock = {
      incident: {
        count: jest.fn().mockResolvedValue(0),
        groupBy: jest.fn().mockResolvedValue([]),
      },
    };

    const module = await Test.createTestingModule({
      providers: [
        IncidentService,
        { provide: PrismaService, useValue: prismaMock },
        {
          provide: NotificationsService,
          useValue: {
            sendIncidentAlert: jest.fn(),
            sendAttendanceReport: jest.fn(),
          },
        },
        // IncidentService publishes to the realtime stream as well as creating
        // notifications; the spec predated that dependency.
        {
          provide: RealtimeService,
          useValue: { publish: jest.fn(), subscribe: jest.fn() },
        },
      ],
    }).compile();

    service = module.get<IncidentService>(IncidentService);
  });

  describe('getMetrics', () => {
    it('returns total, daily, weekly, open, resolved and byType map', async () => {
      prismaMock.incident.groupBy.mockResolvedValue([
        { incidentType: 'THEFT', _count: { id: 3 } },
        { incidentType: 'FIRE', _count: { id: 2 } },
        { incidentType: 'MEDICAL', _count: { id: 1 } },
      ]);

      const result = await service.getMetrics({ organizationId });

      expect(result.total).toBe(0);
      expect(result.daily).toBe(0);
      expect(result.weekly).toBe(0);
      expect(result.open).toBe(0);
      expect(result.resolved).toBe(0);
      expect(result.byType).toEqual({ THEFT: 3, FIRE: 2, MEDICAL: 1 });
      expect(result.filters).toEqual({
        startDate: null,
        endDate: null,
        type: null,
      });
    });

    it('builds a 7-day time-series when no range is provided', async () => {
      const result = await service.getMetrics({ organizationId });

      expect(result.dailyBreakdown).toHaveLength(7);
      expect(result.dailyBreakdown[6].date).toBe(todayKey());
      for (let i = 1; i < result.dailyBreakdown.length; i++) {
        expect(
          result.dailyBreakdown[i].date > result.dailyBreakdown[i - 1].date,
        ).toBe(true);
      }
    });

    it('builds daily buckets within the requested range', async () => {
      const startDate = daysAgo(3);
      const endDate = daysAgo(1);

      prismaMock.incident.count.mockImplementation(({ where }: any) =>
        Promise.resolve(where.reportedAt ? 1 : 0),
      );

      const result = await service.getMetrics({
        organizationId,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
      });

      expect(result.dailyBreakdown).toHaveLength(3);
      expect(result.dailyBreakdown[0].date).toBe(dateKey(startDate));
      expect(result.dailyBreakdown[2].date).toBe(dateKey(endDate));
      expect(
        result.dailyBreakdown.every((d: { count: number }) => d.count === 1),
      ).toBe(true);
    });

    it('caps the daily time-series at 31 days', async () => {
      const result = await service.getMetrics({
        organizationId,
        startDate: daysAgo(100).toISOString(),
        endDate: daysAgo(0).toISOString(),
      });

      expect(result.dailyBreakdown).toHaveLength(31);
      expect(result.dailyBreakdown[30].date).toBe(todayKey());
    });

    it('scopes all aggregations to the organization and type filter', async () => {
      await service.getMetrics({ organizationId, type: 'FIRE' });

      const countCalls = prismaMock.incident.count.mock.calls;
      expect(countCalls.length).toBeGreaterThan(0);
      for (const [args] of countCalls) {
        expect(args.where.site).toEqual({ organizationId });
        expect(args.where.incidentType).toBe('FIRE');
      }
      expect(prismaMock.incident.groupBy).toHaveBeenCalledWith(
        expect.objectContaining({
          by: ['incidentType'],
          where: expect.objectContaining({
            incidentType: 'FIRE',
            site: { organizationId },
          }),
        }),
      );
    });

    it('rejects an invalid startDate', async () => {
      await expect(
        service.getMetrics({ organizationId, startDate: 'not-a-date' }),
      ).rejects.toThrow(BadRequestException);
    });

    it('rejects an invalid endDate', async () => {
      await expect(
        service.getMetrics({ organizationId, endDate: 'not-a-date' }),
      ).rejects.toThrow(BadRequestException);
    });

    it('rejects a startDate after endDate', async () => {
      await expect(
        service.getMetrics({
          organizationId,
          startDate: '2026-07-10',
          endDate: '2026-07-01',
        }),
      ).rejects.toThrow(BadRequestException);
    });

    it('wraps database failures in an InternalServerErrorException', async () => {
      prismaMock.incident.count.mockRejectedValue(new Error('db unavailable'));

      await expect(service.getMetrics({ organizationId })).rejects.toThrow(
        InternalServerErrorException,
      );
    });
  });
});

import {
  Injectable,
  NotFoundException,
  Logger,
  BadRequestException,
  InternalServerErrorException,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../../database/prisma.service';
import {
  ReportIncidentDto,
  UpdateIncidentDto,
  UpdateIncidentStatusDto,
} from './dto/incident.dto';
import { NotificationsService } from '../notifications/notifications.service';
import { RealtimeService } from '../realtime/realtime.service';

@Injectable()
export class IncidentService {
  private readonly logger = new Logger(IncidentService.name);

  constructor(
    private prisma: PrismaService,
    private notifications: NotificationsService,
    private realtime: RealtimeService,
  ) {}

  async reportIncident(
    dto: ReportIncidentDto,
    user: { id: string; organizationId: string },
  ) {
    const site = await this.prisma.site.findFirst({
      where: { id: dto.siteId, organizationId: user.organizationId },
    });
    if (!site)
      throw new NotFoundException('Site not found in your organization');

    const incident = await this.prisma.incident.create({
      data: {
        title: dto.title,
        description: dto.description,
        incidentType: dto.type,
        severity: dto.severity,
        status: 'OPEN',
        occurrenceTime: new Date(),
        siteId: dto.siteId,
        reporterId: user.id,
        reportedAt: new Date(),
        guardsInvolved: JSON.stringify(dto.involvedParties || []),
        photos: JSON.stringify(dto.mediaUrls || []),
        videos: '[]',
        voiceNotes: '[]',
        witnesses: '[]',
        actionsTaken: '',
        investigationStatus: 'OPEN',
      },
    });

    // Trigger notification (fire-and-forget, don't block response)
    this.notifications
      .sendIncidentAlert({
        incidentId: incident.id,
        type: dto.type,
        severity: dto.severity,
        siteId: dto.siteId,
        siteName: site.name,
        description: dto.description,
      })
      .catch((err) => this.logger.warn('Notification failed:', err.message));

    // Real-time push to the command center
    this.realtime.publish(user.organizationId, 'incident:created', {
      id: incident.id,
      title: dto.title,
      type: dto.type,
      severity: dto.severity,
      status: 'OPEN',
      siteId: dto.siteId,
      siteName: site.name,
      reportedAt: incident.reportedAt.toISOString(),
    });

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: user.id,
          action: 'INCIDENT_CREATED',
          entity: 'Incident',
          entityId: incident.id,
          newValues: JSON.stringify({ type: dto.type, severity: dto.severity }),
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch((err) => this.logger.warn('Audit log failed:', err.message));

    return incident;
  }

  async updateStatus(
    id: string,
    dto: UpdateIncidentStatusDto,
    organizationId: string,
  ) {
    const incident = await this.prisma.incident.findFirst({
      where: { id, site: { organizationId } },
    });
    if (!incident) throw new NotFoundException('Incident not found');

    return this.prisma.incident.update({
      where: { id },
      data: {
        status: dto.status,
        investigationStatus: dto.status,
        resolutionNotes: dto.resolutionNotes,
      },
    });
  }

  async update(id: string, dto: UpdateIncidentDto, organizationId: string) {
    const incident = await this.prisma.incident.findFirst({
      where: { id, site: { organizationId } },
    });
    if (!incident) throw new NotFoundException('Incident not found');

    const data: any = {};
    if (dto.title) data.title = dto.title;
    if (dto.description) data.description = dto.description;
    if (dto.type) data.incidentType = dto.type;
    if (dto.severity) data.severity = dto.severity;
    if (dto.siteId) data.siteId = dto.siteId;
    if (dto.status) {
      data.status = dto.status;
      data.investigationStatus = dto.status;
    }
    if (dto.resolutionNotes !== undefined)
      data.resolutionNotes = dto.resolutionNotes;
    if (dto.actionsTaken !== undefined) data.actionsTaken = dto.actionsTaken;
    if (dto.mediaUrls) data.photos = JSON.stringify(dto.mediaUrls);
    if (dto.involvedParties)
      data.guardsInvolved = JSON.stringify(dto.involvedParties);

    return this.prisma.incident.update({ where: { id }, data });
  }

  async getMetrics(query: {
    organizationId: string;
    startDate?: string;
    endDate?: string;
    type?: string;
  }) {
    const { organizationId } = query;
    const startDate = query.startDate ? new Date(query.startDate) : undefined;
    const endDate = query.endDate ? new Date(query.endDate) : undefined;

    if (startDate && Number.isNaN(startDate.getTime())) {
      throw new BadRequestException(`Invalid startDate: "${query.startDate}"`);
    }
    if (endDate && Number.isNaN(endDate.getTime())) {
      throw new BadRequestException(`Invalid endDate: "${query.endDate}"`);
    }
    if (startDate && endDate && startDate > endDate) {
      throw new BadRequestException('startDate must be before endDate');
    }

    try {
      // Aggregation filter shared by all metric queries
      const where: Prisma.IncidentWhereInput = {
        site: { organizationId },
        ...(query.type ? { incidentType: query.type } : {}),
        ...(startDate || endDate
          ? {
              reportedAt: {
                ...(startDate ? { gte: startDate } : {}),
                ...(endDate ? { lte: endDate } : {}),
              },
            }
          : {}),
      };

      // Organization-scoped calendar metrics (daily/weekly ignore the
      // optional date range so they stay "live" stats)
      const orgWhere: Prisma.IncidentWhereInput = {
        site: { organizationId },
        ...(query.type ? { incidentType: query.type } : {}),
      };

      // Current calendar day window (local time)
      const todayStart = new Date();
      todayStart.setHours(0, 0, 0, 0);
      const tomorrowStart = new Date(todayStart);
      tomorrowStart.setDate(tomorrowStart.getDate() + 1);

      const weekAgo = new Date(todayStart);
      weekAgo.setDate(weekAgo.getDate() - 7);

      // Run all aggregates in parallel; Prisma compiles these to SQL
      // COUNT / GROUP BY queries backed by the Incident indexes.
      const [total, daily, weekly, open, resolved, byTypeRows, dailyBreakdown] =
        await Promise.all([
          this.prisma.incident.count({ where }),
          this.prisma.incident.count({
            where: {
              ...orgWhere,
              reportedAt: { gte: todayStart, lt: tomorrowStart },
            },
          }),
          this.prisma.incident.count({
            where: { ...orgWhere, reportedAt: { gte: weekAgo } },
          }),
          this.prisma.incident.count({
            where: { ...where, status: { in: ['OPEN', 'INVESTIGATING'] } },
          }),
          this.prisma.incident.count({
            where: { ...where, status: { in: ['RESOLVED', 'CLOSED'] } },
          }),
          this.prisma.incident.groupBy({
            by: ['incidentType'],
            where,
            _count: { id: true },
          }),
          this.getDailyBreakdown(where, startDate, endDate),
        ]);

      // { type_name: count } dictionary per the endpoint spec
      const byType: Record<string, number> = {};
      for (const row of byTypeRows) {
        byType[row.incidentType] = row._count.id;
      }

      return {
        total,
        daily,
        weekly,
        open,
        resolved,
        byType,
        dailyBreakdown,
        filters: {
          startDate: query.startDate || null,
          endDate: query.endDate || null,
          type: query.type || null,
        },
      };
    } catch (error) {
      this.logger.error(
        'Failed to compute incident metrics',
        error instanceof Error ? error.stack : String(error),
      );
      throw new InternalServerErrorException(
        'Failed to compute incident metrics',
      );
    }
  }

  /**
   * Time-series of daily incident counts. Defaults to the last 7 days and
   * honors the startDate/endDate range when provided. Bounded to 31 days
   * so the per-day COUNT queries stay cheap.
   */
  private async getDailyBreakdown(
    where: Prisma.IncidentWhereInput,
    startDate?: Date,
    endDate?: Date,
  ) {
    const todayStart = new Date();
    todayStart.setHours(0, 0, 0, 0);

    let from: Date;
    let to: Date;
    if (startDate || endDate) {
      from = new Date(startDate ?? todayStart);
      from.setHours(0, 0, 0, 0);
      to = new Date(endDate ?? todayStart);
      to.setHours(0, 0, 0, 0);
    } else {
      from = new Date(todayStart);
      from.setDate(from.getDate() - 6);
      to = new Date(todayStart);
    }

    // Walk backwards from `to`, keeping at most MAX_DAYS buckets
    const MAX_DAYS = 31;
    const days: Date[] = [];
    for (
      const cursor = new Date(to);
      days.length < MAX_DAYS;
      cursor.setDate(cursor.getDate() - 1)
    ) {
      days.push(new Date(cursor));
      if (cursor.getTime() <= from.getTime()) break;
    }
    days.reverse();

    return Promise.all(
      days.map(async (day) => {
        const nextDay = new Date(day);
        nextDay.setDate(nextDay.getDate() + 1);
        const count = await this.prisma.incident.count({
          where: { ...where, reportedAt: { gte: day, lt: nextDay } },
        });
        return { date: this.formatDateKey(day), count };
      }),
    );
  }

  private formatDateKey(date: Date): string {
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${date.getFullYear()}-${month}-${day}`;
  }

  async findAll(query: {
    page?: number;
    limit?: number;
    siteId?: string;
    status?: string;
    type?: string;
    search?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 10;
    const skip = (page - 1) * limit;

    const where: any = { site: { organizationId: query.organizationId } };
    if (query.siteId) where.siteId = query.siteId;
    if (query.status) where.status = query.status;
    if (query.type) where.incidentType = query.type;
    if (query.search) {
      where.OR = [
        { title: { contains: query.search, mode: 'insensitive' } },
        { description: { contains: query.search, mode: 'insensitive' } },
        { incidentType: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    const [data, total] = await Promise.all([
      this.prisma.incident.findMany({
        where,
        skip,
        take: limit,
        orderBy: { reportedAt: 'desc' },
        include: {
          site: {
            select: {
              id: true,
              name: true,
              client: { select: { companyName: true } },
            },
          },
          reporter: { select: { id: true, firstName: true, lastName: true } },
        },
      }),
      this.prisma.incident.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }

  async remove(id: string, organizationId: string) {
    const incident = await this.prisma.incident.findFirst({
      where: { id, site: { organizationId } },
    });
    if (!incident) throw new NotFoundException('Incident not found');
    return this.prisma.incident.delete({ where: { id } });
  }

  async findOne(id: string) {
    const incident = await this.prisma.incident.findUnique({
      where: { id },
      include: {
        site: { include: { client: true } },
        reporter: true,
      },
    });
    if (!incident) throw new NotFoundException('Incident not found');
    return incident;
  }
}

