import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

const SEVERITY_WEIGHT: Record<string, number> = {
  CRITICAL: 40,
  HIGH: 25,
  MEDIUM: 12,
  LOW: 5,
};

const clamp = (n: number, min = 0, max = 100) =>
  Math.max(min, Math.min(max, Math.round(n)));

/**
 * Napoleon — Spectra's intelligence layer. Deterministic, explainable signals
 * computed from live operational data (attendance, incidents, patrols, guard
 * performance). Each insight is rule-based so operators can trust and audit
 * it; the surface is designed so a learned model can slot in behind the same
 * endpoints later.
 */
@Injectable()
export class NapoleonService {
  private readonly logger = new Logger(NapoleonService.name);

  constructor(private prisma: PrismaService) {}

  private startOfWindow(days: number): Date {
    const d = new Date();
    d.setDate(d.getDate() - days);
    d.setHours(0, 0, 0, 0);
    return d;
  }

  // ── Public surface ────────────────────────────────────────────────────────

  async getOverview(organizationId: string) {
    const since30 = this.startOfWindow(30);
    const since14 = this.startOfWindow(14);

    const [sites, guards, incidents, attendance, patrols] = await Promise.all([
      this.prisma.site.findMany({
        where: { organizationId },
        select: { id: true, name: true, riskLevel: true },
      }),
      this.prisma.guard.findMany({
        where: { organizationId, status: 'ACTIVE' },
        select: { id: true, performanceScore: true },
      }),
      this.prisma.incident.findMany({
        where: { site: { organizationId }, reportedAt: { gte: since30 } },
        select: {
          severity: true,
          status: true,
          siteId: true,
          reportedAt: true,
        },
      }),
      this.prisma.attendance.findMany({
        where: { guard: { organizationId }, createdAt: { gte: since14 } },
        select: { isLate: true, isAbsent: true, status: true },
      }),
      this.prisma.patrolRecord.findMany({
        where: { guard: { organizationId }, createdAt: { gte: since14 } },
        select: { completionPercentage: true },
      }),
    ]);

    const openIncidents = incidents.filter((i) => i.status === 'OPEN').length;
    const avgPerformance =
      guards.length === 0
        ? 0
        : guards.reduce((s, g) => s + (g.performanceScore ?? 0), 0) /
          guards.length;
    const lateRate =
      attendance.length === 0
        ? 0
        : (attendance.filter((a) => a.isLate || a.status === 'FLAGGED').length /
            attendance.length) *
          100;
    const patrolCompletion =
      patrols.length === 0
        ? 0
        : patrols.reduce((s, p) => s + p.completionPercentage, 0) /
          patrols.length;

    const healthScore = clamp(
      avgPerformance * 0.4 +
        (100 - openIncidents * 3) * 0.25 +
        (100 - lateRate) * 0.2 +
        patrolCompletion * 0.15,
    );

    const insights = await this.buildInsights(organizationId, {
      sites,
      guards,
      incidents,
      attendance,
      patrols,
      lateRate,
      patrolCompletion,
      avgPerformance,
    });

    return {
      generatedAt: new Date().toISOString(),
      healthScore,
      openIncidents,
      avgGuardPerformance: Math.round(avgPerformance),
      lateCheckInRate: Math.round(lateRate * 10) / 10,
      patrolCompletionRate: Math.round(patrolCompletion * 10) / 10,
      atRiskGuardCount: guards.filter((g) => (g.performanceScore ?? 0) < 60)
        .length,
      siteCount: sites.length,
      insights,
    };
  }

  async getRiskBySite(organizationId: string) {
    const sites = await this.prisma.site.findMany({
      where: { organizationId },
      select: { id: true, name: true, riskLevel: true },
    });

    const since = this.startOfWindow(30);
    const [incidents, attendance] = await Promise.all([
      this.prisma.incident.findMany({
        where: { site: { organizationId }, reportedAt: { gte: since } },
        select: {
          severity: true,
          siteId: true,
          reportedAt: true,
          status: true,
        },
      }),
      this.prisma.attendance.findMany({
        where: { guard: { organizationId }, createdAt: { gte: since } },
        select: { siteId: true, isLate: true, isAbsent: true, status: true },
      }),
    ]);

    // Patrol completion by site (via route → site)
    const patrolRoutes = await this.prisma.patrolRoute.findMany({
      where: { site: { organizationId } },
      select: { id: true, siteId: true },
    });
    const routeToSite = new Map(patrolRoutes.map((r) => [r.id, r.siteId]));
    const patrolRecords = await this.prisma.patrolRecord.findMany({
      where: { guard: { organizationId }, createdAt: { gte: since } },
      select: { routeId: true, completionPercentage: true },
    });
    const patrolBySite = new Map<string, number[]>();
    for (const p of patrolRecords) {
      const siteId = routeToSite.get(p.routeId);
      if (!siteId) continue;
      if (!patrolBySite.has(siteId)) patrolBySite.set(siteId, []);
      patrolBySite.get(siteId)!.push(p.completionPercentage);
    }

    const bySite = new Map<string, { incidents: any[]; attendance: any[] }>();
    for (const s of sites) bySite.set(s.id, { incidents: [], attendance: [] });
    for (const i of incidents) bySite.get(i.siteId)?.incidents.push(i);
    for (const a of attendance) bySite.get(a.siteId)?.attendance.push(a);

    const result = sites.map((site) => {
      const { incidents: siteInc, attendance: siteAtt } = bySite.get(
        site.id,
      ) ?? {
        incidents: [],
        attendance: [],
      };
      const sitePatrols = patrolBySite.get(site.id) ?? [];
      const incidentScore = siteInc.reduce(
        (s, i) => s + (SEVERITY_WEIGHT[i.severity] ?? 5),
        0,
      );
      const lateRate =
        siteAtt.length === 0
          ? 0
          : (siteAtt.filter((a) => a.isLate || a.status === 'FLAGGED').length /
              siteAtt.length) *
            100;
      const patrolCompletion =
        sitePatrols.length === 0
          ? 100
          : sitePatrols.reduce((s, p) => s + p, 0) / sitePatrols.length;

      const riskScore = clamp(
        Math.min(incidentScore, 60) +
          lateRate * 0.25 +
          (100 - patrolCompletion) * 0.35 +
          (site.riskLevel === 'CRITICAL'
            ? 10
            : site.riskLevel === 'HIGH'
              ? 6
              : site.riskLevel === 'MEDIUM'
                ? 3
                : 0),
      );

      const hourBuckets = new Array(24).fill(0);
      for (const i of siteInc) hourBuckets[new Date(i.reportedAt).getHours()]++;
      const peakHour = hourBuckets.reduce(
        (best, c, h) => (c > hourBuckets[best] ? h : best),
        0,
      );

      return {
        siteId: site.id,
        siteName: site.name,
        riskLevel: site.riskLevel,
        riskScore,
        incidentCount30d: siteInc.length,
        openIncidents30d: siteInc.filter((i) => i.status === 'OPEN').length,
        lateCheckInRate: Math.round(lateRate * 10) / 10,
        patrolCompletionRate: Math.round(patrolCompletion * 10) / 10,
        peakIncidentHour: hourBuckets[peakHour] > 0 ? peakHour : null,
      };
    });

    result.sort((a, b) => b.riskScore - a.riskScore);
    return result;
  }

  async getAtRiskGuards(organizationId: string) {
    const since = this.startOfWindow(14);
    const [guards, attendance] = await Promise.all([
      this.prisma.guard.findMany({
        where: { organizationId, status: 'ACTIVE' },
        select: {
          id: true,
          fullName: true,
          performanceScore: true,
          currentShift: true,
          assignedSite: { select: { name: true } },
        },
      }),
      this.prisma.attendance.findMany({
        where: { guard: { organizationId }, createdAt: { gte: since } },
        select: {
          guardId: true,
          isLate: true,
          isAbsent: true,
          status: true,
          createdAt: true,
        },
      }),
    ]);

    const byGuard = new Map<
      string,
      { late: number; flagged: number; absent: number; days: Set<string> }
    >();
    for (const g of guards)
      byGuard.set(g.id, { late: 0, flagged: 0, absent: 0, days: new Set() });
    for (const a of attendance) {
      const row = byGuard.get(a.guardId);
      if (!row) continue;
      row.days.add(a.createdAt.toISOString().slice(0, 10));
      if (a.isAbsent || a.status === 'ABSENT') row.absent++;
      else if (a.isLate) row.late++;
      if (a.status === 'FLAGGED') row.flagged++;
    }

    return guards
      .map((g) => {
        const stats = byGuard.get(g.id) ?? {
          late: 0,
          flagged: 0,
          absent: 0,
          days: new Set(),
        };
        const workedDays = stats.days.size;
        const reliability =
          workedDays === 0
            ? 100
            : Math.max(
                0,
                Math.round(
                  ((workedDays - stats.late - stats.absent) /
                    Math.max(workedDays, 1)) *
                    100,
                ),
              );

        let riskLevel = 'LOW';
        const riskFactors: string[] = [];
        if (stats.late >= 3) {
          riskLevel = 'MEDIUM';
          riskFactors.push(`${stats.late} late check-ins in 14 days`);
        }
        if (stats.absent >= 2) {
          riskLevel = riskLevel === 'MEDIUM' ? 'HIGH' : 'MEDIUM';
          riskFactors.push(`${stats.absent} absent days in 14 days`);
        }
        if (stats.flagged >= 2) {
          riskLevel = riskLevel === 'HIGH' ? 'HIGH' : 'MEDIUM';
          riskFactors.push(`${stats.flagged} geofence violations`);
        }
        if ((g.performanceScore ?? 100) < 60) {
          riskLevel = 'HIGH';
          riskFactors.push(`performance score ${g.performanceScore}`);
        }

        return {
          guardId: g.id,
          fullName: g.fullName,
          shift: g.currentShift,
          site: g.assignedSite?.name ?? 'Unassigned',
          performanceScore: g.performanceScore ?? 100,
          reliability,
          lateCount: stats.late,
          absentCount: stats.absent,
          flaggedCount: stats.flagged,
          riskLevel,
          riskFactors,
        };
      })
      .filter((g) => g.riskLevel !== 'LOW')
      .sort((a, b) => b.riskFactors.length - a.riskFactors.length);
  }

  // ── Insight rules ─────────────────────────────────────────────────────────

  private async buildInsights(
    _organizationId: string,
    ctx: {
      sites: any[];
      guards: any[];
      incidents: any[];
      attendance: any[];
      patrols: any[];
      lateRate: number;
      patrolCompletion: number;
      avgPerformance: number;
    },
  ): Promise<any[]> {
    const insights: any[] = [];

    const open = ctx.incidents.filter((i) => i.status === 'OPEN').length;
    if (open >= 3) {
      insights.push({
        severity: 'HIGH',
        category: 'INCIDENTS',
        title: `${open} open incidents need attention`,
        detail: `Response has not closed ${open} incident(s) in the last 30 days. Unresolved incidents compound liability and client risk.`,
        recommendation:
          'Assign owners to open incidents and escalate anything over 48 hours old.',
        metric: `${open} open`,
      });
    }

    if (ctx.lateRate > 20) {
      insights.push({
        severity: 'MEDIUM',
        category: 'ATTENDANCE',
        title: `Late check-ins running at ${Math.round(ctx.lateRate)}%`,
        detail:
          'More than 1 in 5 check-ins over the last 14 days was late or flagged outside the geofence.',
        recommendation:
          'Review shift start times and consider SMS reminders 30 minutes before shift.',
        metric: `${Math.round(ctx.lateRate)}%`,
      });
    }

    if (ctx.patrolCompletion < 80) {
      insights.push({
        severity: 'MEDIUM',
        category: 'PATROLS',
        title: `Patrol completion at ${Math.round(ctx.patrolCompletion)}%`,
        detail:
          'Patrol routes are being completed below the 80% target, leaving coverage gaps.',
        recommendation:
          'Reassign under-completed routes to guards on overlapping shifts.',
        metric: `${Math.round(ctx.patrolCompletion)}%`,
      });
    }

    const nightIncidents = ctx.incidents.filter((i) => {
      const h = new Date(i.reportedAt).getHours();
      return h >= 18 || h < 6;
    }).length;
    if (
      nightIncidents > 0 &&
      nightIncidents / Math.max(ctx.incidents.length, 1) > 0.5
    ) {
      insights.push({
        severity: 'MEDIUM',
        category: 'PATTERNS',
        title: `Most incidents occur at night (${Math.round((nightIncidents / ctx.incidents.length) * 100)}%)`,
        detail:
          'Night hours carry the majority of incident load — a sign coverage thins when visibility drops.',
        recommendation:
          'Add a dedicated night supervisor and increase patrol frequency after 20:00.',
        metric: `${nightIncidents}/${ctx.incidents.length}`,
      });
    }

    const lowPerformers = ctx.guards.filter(
      (g) => (g.performanceScore ?? 0) < 60,
    ).length;
    if (lowPerformers > 0) {
      insights.push({
        severity: lowPerformers > 3 ? 'HIGH' : 'MEDIUM',
        category: 'PERSONNEL',
        title: `${lowPerformers} guard(s) scoring below 60`,
        detail:
          'Performance scores indicate attendance and reliability problems that can become attrition risk.',
        recommendation:
          'Schedule check-ins with the at-risk guards and review their site assignments.',
        metric: `${lowPerformers} guards`,
      });
    }

    if (insights.length === 0) {
      insights.push({
        severity: 'INFO',
        category: 'HEALTH',
        title: 'Operations are stable',
        detail:
          'No anomalies detected across attendance, incidents, or patrols in the review window.',
        recommendation:
          'Continue monitoring — Napoleon will alert you the moment a pattern shifts.',
        metric: 'All clear',
      });
    }

    return insights;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';
import { PrismaService } from '../../database/prisma.service';
import { RealtimeService } from '../realtime/realtime.service';
import { PushService } from '../push/push.service';

@Injectable()
export class NotificationsService {
  private readonly logger = new Logger(NotificationsService.name);

  constructor(
    @InjectQueue('notifications') private notificationsQueue: Queue,
    private prisma: PrismaService,
    private realtime: RealtimeService,
    private push: PushService,
  ) {}

  /**
   * Create an in-app notification for a user, fan it out over the realtime
   * stream, and attempt a web-push delivery to their devices.
   */
  async create(
    userId: string,
    organizationId: string,
    title: string,
    message: string,
    type = 'IN_APP',
    url?: string,
  ) {
    const notification = await this.prisma.notification.create({
      data: { userId, title, message, type, status: 'UNREAD' },
    });

    this.realtime.publish(organizationId, 'notification:created', {
      id: notification.id,
      title,
      message,
      type,
      status: 'UNREAD',
      createdAt: notification.createdAt.toISOString(),
      userId,
    });

    // Fire web push (best effort, never blocks)
    if (type !== 'IN_APP') {
      this.sendPush(userId, organizationId, title, message, url).catch(
        () => {},
      );
    }

    return notification;
  }

  async sendPush(
    userId: string,
    organizationId: string,
    title: string,
    message: string,
    url?: string,
  ) {
    const subs = await this.prisma.pushSubscription.findMany({
      where: { userId },
      select: { endpoint: true, p256dh: true, auth: true, id: true },
    });
    if (subs.length === 0) return;

    for (const sub of subs) {
      const status = await this.push.send(sub, title, message, url);
      if (status === 404 || status === 410) {
        await this.prisma.pushSubscription
          .delete({ where: { id: sub.id } })
          .catch(() => {});
      }
    }
    this.logger.debug(`Push sent to ${subs.length} device(s)`);
  }

  async sendIncidentAlert(incidentData: any) {
    // Queue for heavyweight work (email/SMS integration later)
    await this.notificationsQueue.add('incident-alert', incidentData, {
      attempts: 3,
      backoff: { type: 'exponential', delay: 1000 },
      removeOnComplete: true,
    });

    // Immediate in-app + push to command staff
    try {
      const staff = await this.prisma.user.findMany({
        where: {
          organizationId:
            incidentData.organizationId ?? incidentData.site?.organizationId,
          role: { in: ['CEO', 'OPERATIONS_MANAGER', 'HR', 'SUPERVISOR'] },
          isActive: true,
        },
        select: { id: true, organizationId: true },
      });

      for (const user of staff) {
        await this.create(
          user.id,
          user.organizationId,
          `Incident: ${incidentData.title ?? incidentData.type ?? 'New incident'}`,
          `${incidentData.severity ?? ''} ${incidentData.type ?? 'ALERT'} at ${incidentData.siteName ?? 'site'}${incidentData.description ? ` — ${String(incidentData.description).slice(0, 120)}` : ''}`,
          'ALERT',
          incidentData.incidentId
            ? `/incidents/${incidentData.incidentId}`
            : '/incidents',
        ).catch((err) =>
          this.logger.warn(`Incident notification failed: ${err.message}`),
        );
      }
    } catch (err) {
      this.logger.warn(
        `Incident alert fan-out failed: ${(err as Error).message}`,
      );
    }
  }

  async sendAttendanceReport(siteId: string) {
    await this.notificationsQueue.add(
      'attendance-report',
      { siteId },
      {
        attempts: 2,
      },
    );
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { StartPatrolDto, SubmitPatrolLogDto } from './dto/patrol.dto';

// Configurable performance scoring weights
const PERFORMANCE_WEIGHTS = {
  ATTENDANCE: 0.6,
  PATROL: 0.4,
};

@Injectable()
export class PatrolService {
  constructor(private prisma: PrismaService) {}

  async getRoutes(siteId: string, organizationId: string) {
    return this.prisma.patrolRoute.findMany({
      where: { siteId, site: { organizationId } },
      include: {
        checkpoints: { orderBy: { sequenceOrder: 'asc' } },
      },
    });
  }

  async startPatrol(
    dto: StartPatrolDto,
    user: { id: string; organizationId: string },
  ) {
    const route = await this.prisma.patrolRoute.findFirst({
      where: { id: dto.routeId, site: { organizationId: user.organizationId } },
      include: { checkpoints: true },
    });
    if (!route) throw new NotFoundException('Patrol route not found');

    const guardId =
      dto.guardId ??
      (
        await this.prisma.guard.findFirst({
          where: { userId: user.id, organizationId: user.organizationId },
          select: { id: true },
        })
      )?.id;
    if (!guardId)
      throw new NotFoundException('Guard profile not found for this employee');

    // Prevent duplicate in-progress patrols for the same guard
    const existingPatrol = await this.prisma.patrolRecord.findFirst({
      where: { guardId, status: 'IN_PROGRESS' },
    });
    if (existingPatrol) {
      throw new BadRequestException(
        'Guard already has an in-progress patrol. Complete it first.',
      );
    }

    const record = await this.prisma.patrolRecord.create({
      data: {
        routeId: dto.routeId,
        guardId,
        startTime: new Date(),
        status: 'IN_PROGRESS',
        scannedCheckpoints: '[]',
        missedCheckpoints: '[]',
      },
    });

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: user.id,
          action: 'PATROL_STARTED',
          entity: 'PatrolRecord',
          entityId: record.id,
          newValues: JSON.stringify({ routeId: dto.routeId, guardId }),
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return record;
  }

  async submitLog(
    dto: SubmitPatrolLogDto,
    user: { id: string; organizationId: string },
  ) {
    const guard = await this.prisma.guard.findFirst({
      where: { userId: user.id, organizationId: user.organizationId },
      select: { id: true },
    });

    const patrolRecord = await this.prisma.patrolRecord.findFirst({
      where: {
        id: dto.patrolRecordId,
        ...(guard ? { guardId: guard.id } : {}),
      },
      include: { route: { include: { checkpoints: true } } },
    });

    if (!patrolRecord) throw new NotFoundException('Patrol record not found');
    if (patrolRecord.status === 'COMPLETED')
      throw new BadRequestException('Patrol already completed');

    const expectedCheckpoints = patrolRecord.route.checkpoints.map(
      (checkpoint: { id: string }) => checkpoint.id,
    );
    const scannedIds = dto.scans.map(
      (scan: { checkpointId: string }) => scan.checkpointId,
    );

    const missedCheckpoints = expectedCheckpoints.filter(
      (id: string) => !scannedIds.includes(id),
    );
    const completionPercentage =
      expectedCheckpoints.length > 0
        ? (scannedIds.length / expectedCheckpoints.length) * 100
        : 0;

    // Create individual PatrolLog entries for each scanned checkpoint
    for (const scan of dto.scans) {
      await this.prisma.patrolLog.create({
        data: {
          patrolRouteId: patrolRecord.routeId,
          checkpointId: scan.checkpointId,
          guardId: patrolRecord.guardId,
          scannedAt: new Date(scan.scanTime),
          latitude: scan.latitude,
          longitude: scan.longitude,
          isLate: false,
          isMissed: false,
        },
      });
    }

    // Create PatrolLog entries for missed checkpoints
    for (const missedId of missedCheckpoints) {
      const checkpoint = patrolRecord.route.checkpoints.find(
        (cp) => cp.id === missedId,
      );
      if (checkpoint) {
        await this.prisma.patrolLog.create({
          data: {
            patrolRouteId: patrolRecord.routeId,
            checkpointId: missedId,
            guardId: patrolRecord.guardId,
            scannedAt: new Date(),
            latitude: checkpoint.expectedLatitude,
            longitude: checkpoint.expectedLongitude,
            isMissed: true,
          },
        });
      }
    }

    const record = await this.prisma.patrolRecord.update({
      where: { id: dto.patrolRecordId },
      data: {
        endTime: new Date(),
        status: 'COMPLETED',
        scannedCheckpoints: JSON.stringify(dto.scans),
        missedCheckpoints: JSON.stringify(missedCheckpoints),
        completionPercentage,
        incidentReportId: dto.incidentReportId,
        generalNotes: dto.generalNotes,
      },
    });

    // Update guard performance score using configurable weights
    if (record.guardId) {
      const totalPatrols = await this.prisma.patrolRecord.count({
        where: { guardId: record.guardId },
      });
      const completedPatrols = await this.prisma.patrolRecord.count({
        where: { guardId: record.guardId, status: 'COMPLETED' },
      });
      const patrolRate =
        totalPatrols > 0
          ? Math.round((completedPatrols / totalPatrols) * 100)
          : 100;

      const guard = await this.prisma.guard.findUnique({
        where: { id: record.guardId },
      });
      if (guard) {
        // Use configurable weights from PERFORMANCE_WEIGHTS
        const newScore = Math.round(
          guard.performanceScore * PERFORMANCE_WEIGHTS.ATTENDANCE +
            patrolRate * PERFORMANCE_WEIGHTS.PATROL,
        );
        await this.prisma.guard.update({
          where: { id: record.guardId },
          data: { performanceScore: Math.max(0, Math.min(100, newScore)) },
        });
      }
    }

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: user.id,
          action: 'PATROL_COMPLETED',
          entity: 'PatrolRecord',
          entityId: record.id,
          newValues: JSON.stringify({
            completionPercentage,
            totalCheckpoints: expectedCheckpoints.length,
            scannedCheckpoints: scannedIds.length,
            missedCheckpoints: missedCheckpoints.length,
          }),
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return record;
  }

  async getPatrolHistory(query: {
    page?: number;
    limit?: number;
    siteId?: string;
    guardId?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 10;
    const skip = (page - 1) * limit;

    const where: any = {
      route: { site: { organizationId: query.organizationId } },
    };
    if (query.guardId) where.guardId = query.guardId;
    if (query.siteId) where.route = { ...where.route, siteId: query.siteId };

    const [data, total] = await Promise.all([
      this.prisma.patrolRecord.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: {
          guard: { select: { id: true, fullName: true } },
          route: {
            select: {
              id: true,
              name: true,
              site: { select: { id: true, name: true } },
            },
          },
        },
      }),
      this.prisma.patrolRecord.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }
}

import { Injectable, Logger, OnModuleInit } from '@nestjs/common';
import {
  generateKeyPairSync,
  createECDH,
  createSign,
  createCipheriv,
  hkdfSync,
  randomBytes,
} from 'crypto';
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';

const VAPID_KEYS_FILE = join(process.cwd(), 'vapid-keys.json');

interface VapidKeys {
  publicKey: string; // base64url uncompressed 65-byte point
  privateKey: string; // base64url 32-byte private scalar
}

interface PushSubscriptionRow {
  endpoint: string;
  p256dh: string;
  auth: string;
}

/** Convert a DER ECDSA signature to the raw r||s form used in JWT. */
function derToRawSignature(der: Buffer, size = 32): Buffer {
  let offset = 0;
  if (der[offset] !== 0x30) throw new Error('Invalid DER signature');
  offset += 2;
  const readInt = () => {
    if (der[offset] !== 0x02) throw new Error('Invalid DER integer');
    let len = der[offset + 1];
    let start = offset + 2;
    offset = start + len;
    // Strip leading zero padding
    while (len > 1 && der[start] === 0x00) {
      start++;
      len--;
    }
    const buf = Buffer.alloc(size);
    const copy = Math.min(len, size);
    der.copy(buf, size - copy, start, start + copy);
    return buf;
  };
  const r = readInt();
  const s = readInt();
  return Buffer.concat([r, s]);
}

@Injectable()
export class PushService implements OnModuleInit {
  private readonly logger = new Logger(PushService.name);
  private vapid!: VapidKeys;
  private readonly subject =
    process.env.VAPID_SUBJECT || 'mailto:ops@spectra.technology';

  onModuleInit() {
    this.vapid = this.loadOrCreateKeys();
    this.logger.log('Web Push ready (VAPID keys loaded)');
  }

  getPublicKey(): string {
    return this.vapid.publicKey;
  }

  private loadOrCreateKeys(): VapidKeys {
    if (existsSync(VAPID_KEYS_FILE)) {
      try {
        const parsed = JSON.parse(readFileSync(VAPID_KEYS_FILE, 'utf8'));
        if (parsed.publicKey && parsed.privateKey) return parsed;
      } catch {
        this.logger.warn('Could not parse vapid-keys.json — regenerating');
      }
    }
    const { publicKey, privateKey } = generateKeyPairSync('ec', {
      namedCurve: 'prime256v1',
    });
    const keys: VapidKeys = {
      publicKey: publicKey
        .export({ type: 'spki', format: 'der' })
        .subarray(-65)
        .toString('base64url'),
      privateKey: privateKey
        .export({ type: 'pkcs8', format: 'der' })
        .subarray(-32)
        .toString('base64url'),
    };
    try {
      writeFileSync(VAPID_KEYS_FILE, JSON.stringify(keys));
    } catch (err) {
      this.logger.warn(
        `Could not persist VAPID keys: ${(err as Error).message}`,
      );
    }
    this.logger.log('Generated new VAPID keypair');
    return keys;
  }

  /** Build the VAPID Authorization header value for an endpoint's origin. */
  private vapidHeader(endpoint: string): string {
    const url = new URL(endpoint);
    const audience = `${url.protocol}//${url.host}`;
    const now = Math.floor(Date.now() / 1000);

    const header = Buffer.from(
      JSON.stringify({ typ: 'JWT', alg: 'ES256' }),
    ).toString('base64url');
    const claims = Buffer.from(
      JSON.stringify({
        aud: audience,
        exp: now + 12 * 3600,
        sub: this.subject,
      }),
    ).toString('base64url');

    const sign = createSign('sha256');
    sign.update(`${header}.${claims}`);
    const der = sign.sign({
      key: Buffer.from(
        `-----BEGIN PRIVATE KEY-----\n${this.b64urlToB64(this.vapid.privateKey)}\n-----END PRIVATE KEY-----\n`,
      ),
      format: 'der',
      type: 'pkcs8',
    });
    const raw = derToRawSignature(der);
    const token = `${header}.${claims}.${raw.toString('base64url')}`;

    return `vapid t=${token}, k=${this.vapid.publicKey}`;
  }

  private b64urlToB64(s: string): string {
    const pad = s.length % 4 === 0 ? '' : '='.repeat(4 - (s.length % 4));
    return s.replace(/-/g, '+').replace(/_/g, '/') + pad;
  }

  /**
   * Encrypt a payload for a push subscription (RFC 8291 aes128gcm scheme).
   * Returns { body, headers } ready for the POST to the push service.
   */
  private encryptPayload(
    sub: PushSubscriptionRow,
    payload: Buffer,
  ): { body: Buffer; headers: Record<string, string> } {
    const uaPublic = Buffer.from(this.b64urlToB64(sub.p256dh), 'base64');
    const authSecret = Buffer.from(this.b64urlToB64(sub.auth), 'base64');
    const asPublic = Buffer.from(
      this.b64urlToB64(this.vapid.publicKey),
      'base64',
    );

    const ecdh = createECDH('prime256v1');
    ecdh.setPrivateKey(
      Buffer.from(this.b64urlToB64(this.vapid.privateKey), 'base64'),
    );
    const sharedSecret = ecdh.computeSecret(uaPublic); // 32 bytes

    // HKDF (RFC 5869) with sha256 via hkdfSync
    const authInfo = Buffer.concat([
      Buffer.from('WebPush: info', 'utf8'),
      Buffer.from([0x00]),
      uaPublic,
      asPublic,
    ]);
    const ikm = Buffer.from(
      hkdfSync('sha256', sharedSecret, authSecret, authInfo, 32),
    );

    const keyInfo = Buffer.concat([
      Buffer.from('Content-Encoding: aes128gcm', 'utf8'),
      Buffer.from([0x00]),
      uaPublic,
      asPublic,
    ]);
    const cek = Buffer.from(
      hkdfSync('sha256', ikm, Buffer.alloc(0), keyInfo, 16),
    );

    const nonceInfo = Buffer.concat([
      Buffer.from('Content-Encoding: nonce', 'utf8'),
      Buffer.from([0x00]),
      uaPublic,
      asPublic,
    ]);
    const nonce = Buffer.from(
      hkdfSync('sha256', ikm, Buffer.alloc(0), nonceInfo, 12),
    );

    // aes128gcm record: first 2 bytes = padding length (BE), then that many
    // bytes of padding, then the plaintext. 16 bytes of padding minimum.
    const record = Buffer.alloc(payload.length + 2 + 16);
    record.writeUInt16BE(16, 0);
    payload.copy(record, 2 + 16);

    const cipher = createCipheriv('aes-128-gcm', cek, nonce);
    const ciphertext = Buffer.concat([cipher.update(record), cipher.final()]);
    const tag = cipher.getAuthTag();

    // Record header: salt(16) || rs(4 BE) || idlen(1) || id(65)
    const salt = randomBytes(16);
    const rs = 4096;
    const body = Buffer.concat([
      salt,
      Buffer.from([
        (rs >>> 24) & 0xff,
        (rs >>> 16) & 0xff,
        (rs >>> 8) & 0xff,
        rs & 0xff,
      ]),
      Buffer.from([asPublic.length]),
      asPublic,
      ciphertext,
      tag,
    ]);

    return {
      body,
      headers: {
        'Content-Encoding': 'aes128gcm',
        'Content-Type': 'application/octet-stream',
        TTL: '2419200',
        Urgency: 'high',
      },
    };
  }

  /**
   * Send a push notification to a single subscription. Returns the HTTP status
   * (0 on local error). A 404/410 means the subscription is dead.
   */
  async send(
    sub: PushSubscriptionRow,
    title: string,
    body: string,
    url?: string,
  ): Promise<number> {
    try {
      const payload = Buffer.from(
        JSON.stringify({ title, body, url: url ?? '/', ts: Date.now() }),
      );
      const { body: encrypted, headers } = this.encryptPayload(sub, payload);

      const res = await fetch(sub.endpoint, {
        method: 'POST',
        headers: {
          ...headers,
          Authorization: this.vapidHeader(sub.endpoint),
        },
        body: encrypted as unknown as BodyInit,
      });

      if (res.status === 404 || res.status === 410) {
        this.logger.warn('Push subscription expired — remove it');
        return res.status;
      }
      if (res.status >= 400) {
        const text = await res.text().catch(() => '');
        this.logger.warn(
          `Push send failed (${res.status}): ${text.slice(0, 200)}`,
        );
      }
      return res.status;
    } catch (err) {
      this.logger.warn(`Push send error: ${(err as Error).message}`);
      return 0;
    }
  }
}

import {
  Controller,
  Get,
  Req,
  Res,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import type { Request, Response } from 'express';
import { JwtService } from '@nestjs/jwt';
import { RealtimeService } from './realtime.service';

/**
 * Server-Sent Events endpoint. The browser connects via EventSource and
 * receives domain events (incidents, check-ins, notifications) in real time —
 * no polling, no WebSocket dependency. Auth is resolved from the `token`
 * query param (EventSource cannot set headers) or the access cookie.
 */
@Controller('realtime')
export class RealtimeController {
  private readonly logger = new Logger(RealtimeController.name);

  constructor(
    private realtime: RealtimeService,
    private jwt: JwtService,
  ) {}

  @Get('stream')
  async stream(@Req() req: Request, @Res() res: Response) {
    const token =
      (req.query.token as string) || (req.cookies?.access_token as string);
    if (!token) throw new UnauthorizedException('Missing token');

    let payload: any;
    try {
      payload = this.jwt.verify(token);
    } catch {
      throw new UnauthorizedException('Invalid or expired token');
    }

    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    });

    // Initial comment to open the stream
    res.write(': connected\n\n');

    const heartbeat = setInterval(() => {
      res.write(': ping\n\n');
    }, 25000);

    const unsubscribe = this.realtime.subscribe(
      payload.organizationId,
      (_event, message) => {
        res.write(`data: ${message}\n\n`);
      },
    );

    req.on('close', () => {
      clearInterval(heartbeat);
      unsubscribe();
      res.end();
    });

    this.logger.log(`SSE client connected (org ${payload.organizationId})`);
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import PDFDocument from 'pdfkit';
import { PrismaService } from '../../database/prisma.service';

@Injectable()
export class ReportsService {
  constructor(private prisma: PrismaService) {}

  async generateDailySiteReport(siteId: string): Promise<Buffer> {
    const site = await this.prisma.site.findUnique({
      where: { id: siteId },
      include: { client: true },
    });

    if (!site) throw new NotFoundException('Site not found');

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);

    const [
      todayAttendance,
      totalGuards,
      todayIncidents,
      lateCount,
      absentCount,
      todayPatrols,
    ] = await Promise.all([
      this.prisma.attendance.count({
        where: {
          siteId,
          checkInTime: { gte: today, lt: tomorrow },
          status: { not: 'ABSENT' },
        },
      }),
      this.prisma.guard.count({
        where: { assignedSiteId: siteId, status: 'ACTIVE' },
      }),
      this.prisma.incident.count({
        where: { siteId, reportedAt: { gte: today, lt: tomorrow } },
      }),
      this.prisma.attendance.count({
        where: {
          siteId,
          checkInTime: { gte: today, lt: tomorrow },
          isLate: true,
        },
      }),
      this.prisma.attendance.count({
        where: {
          siteId,
          checkInTime: { gte: today, lt: tomorrow },
          status: 'ABSENT',
        },
      }),
      this.prisma.patrolRecord.count({
        where: {
          route: { siteId },
          startTime: { gte: today, lt: tomorrow },
          status: 'COMPLETED',
        },
      }),
    ]);

    const recentIncidents = await this.prisma.incident.findMany({
      where: { siteId, reportedAt: { gte: today } },
      take: 10,
      orderBy: { reportedAt: 'desc' },
      select: { title: true, incidentType: true, severity: true },
    });

    const pdfBuffer: Buffer = await new Promise((resolve) => {
      const doc = new PDFDocument({ size: 'A4', margin: 50 });
      const buffers: Buffer[] = [];
      doc.on('data', buffers.push.bind(buffers));
      doc.on('end', () => resolve(Buffer.concat(buffers)));

      // Header
      doc.fontSize(20).text('SPECTRA OPS', { align: 'center' });
      doc.moveDown();
      doc.fontSize(16).text('Daily Operations Report', { align: 'center' });
      doc.moveDown(2);

      // Site Info
      const clientName = site.client?.companyName || 'Deleted Client';
      doc.fontSize(12).font('Helvetica-Bold').text(`Site: ${site.name}`);
      doc.font('Helvetica').text(`Client: ${clientName}`);
      doc.text(`Date: ${new Date().toLocaleDateString()}`);
      doc.text(`Risk Level: ${site.riskLevel}`);
      doc.moveDown(2);

      // Attendance Summary
      doc.fontSize(14).font('Helvetica-Bold').text('Attendance Summary');
      doc
        .font('Helvetica')
        .text(`Present: ${todayAttendance} / ${totalGuards}`);
      doc.text(`Late: ${lateCount}`);
      doc.text(`Absent: ${absentCount}`);
      doc.text(`Today's Patrols Completed: ${todayPatrols}`);
      doc.moveDown();

      // Incident Log
      doc.fontSize(14).font('Helvetica-Bold').text('Incident Log');
      if (recentIncidents.length === 0) {
        doc.font('Helvetica').text('No incidents reported today.');
      } else {
        for (const inc of recentIncidents) {
          doc
            .font('Helvetica')
            .text(`- [${inc.severity}] ${inc.incidentType}: ${inc.title}`);
        }
      }
      doc.moveDown();

      // Footer
      doc
        .fontSize(10)
        .fillColor('gray')
        .text(
          'This document is auto-generated by Spectra Operations Intelligence Platform.',
          50,
          750,
          { align: 'center', width: 500 },
        );

      doc.end();
    });

    return pdfBuffer;
  }

  async generateWeeklySiteReport(siteId: string): Promise<Buffer> {
    const site = await this.prisma.site.findUnique({
      where: { id: siteId },
      include: { client: true },
    });
    if (!site) throw new NotFoundException('Site not found');

    const weekAgo = new Date();
    weekAgo.setDate(weekAgo.getDate() - 7);
    weekAgo.setHours(0, 0, 0, 0);

    const [weeklyAttendance, weeklyIncidents, patrolCount] = await Promise.all([
      this.prisma.attendance.count({
        where: { siteId, checkInTime: { gte: weekAgo } },
