    const [incidentCount, attendanceCount, lateCount, patrolCount] =
      await Promise.all([
        this.prisma.incident.count({ where: { site: { clientId } } }),
        this.prisma.attendance.count({
          where: { site: { clientId }, checkInTime: { gte: thirtyDaysAgo } },
        }),
        this.prisma.attendance.count({
          where: {
            site: { clientId },
            checkInTime: { gte: thirtyDaysAgo },
            isLate: true,
          },
        }),
        this.prisma.patrolRecord.count({
          where: { route: { site: { clientId } } },
        }),
      ]);

    const recentIncidents = await this.prisma.incident.findMany({
      where: { site: { clientId } },
      orderBy: { reportedAt: 'desc' },
      take: 15,
      select: {
        title: true,
        incidentType: true,
        severity: true,
        status: true,
        reportedAt: true,
        site: { select: { name: true } },
      },
    });

    const pdfBuffer: Buffer = await new Promise((resolve) => {
      const doc = new PDFDocument({ size: 'A4', margin: 50 });
      const buffers: Buffer[] = [];
      doc.on('data', buffers.push.bind(buffers));
      doc.on('end', () => resolve(Buffer.concat(buffers)));

      doc.fontSize(20).text('SPECTRA OPS', { align: 'center' });
      doc.moveDown();
      doc.fontSize(16).text('Client Operations Summary', { align: 'center' });
      doc.moveDown(2);

      doc.fontSize(12).font('Helvetica-Bold').text(client.companyName);
      doc
        .font('Helvetica')
        .text(`Contact: ${client.contactPerson} · ${client.email}`);
      doc.text(`Generated: ${new Date().toLocaleDateString()}`);
      doc.moveDown(2);

      doc.fontSize(14).font('Helvetica-Bold').text('Portfolio at a Glance');
      doc.font('Helvetica').text(`Deployed Sites: ${sites.length}`);
      doc.text(`Total Guards Allocated: ${client.numberOfGuardsAllocated}`);
      doc.text(`Total Incidents: ${incidentCount}`);
      doc.text(
        `Attendance Records (30d): ${attendanceCount} (${lateCount} late)`,
      );
      doc.text(`Total Patrols: ${patrolCount}`);
      doc.moveDown();

      doc.fontSize(14).font('Helvetica-Bold').text('Site Breakdown');
      for (const s of sites) {
        doc
          .font('Helvetica')
          .text(
            `- ${s.name} (${s.riskLevel} risk): ${s._count.guards} guards, ${s._count.incidents} incidents`,
          );
      }
      doc.moveDown();

      doc.fontSize(14).font('Helvetica-Bold').text('Recent Incidents');
      if (recentIncidents.length === 0) {
        doc.font('Helvetica').text('No incidents on record.');
      } else {
        for (const inc of recentIncidents) {
          doc
            .font('Helvetica')
            .text(
              `- [${inc.severity}] ${inc.incidentType} — ${inc.title} (${inc.site.name}) [${inc.status}]`,
            );
        }
      }
      doc.moveDown();

      doc
        .fontSize(10)
        .fillColor('gray')
        .text(
          'This document is auto-generated by Spectra Operations Intelligence Platform.',
          50,
          750,
          { align: 'center', width: 500 },
        );

      doc.end();
    });

    return pdfBuffer;
  }
}

import { Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { CreateSiteDto, UpdateSiteDto } from './dto/site.dto';

@Injectable()
export class SiteService {
  constructor(private prisma: PrismaService) {}

  async findAll(query: {
    page?: number;
    limit?: number;
    search?: string;
    riskLevel?: string;
    clientId?: string;
    organizationId: string;
  }) {
    const page = query.page || 1;
    const limit = query.limit || 10;
    const skip = (page - 1) * limit;

    const where: any = { organizationId: query.organizationId };
    if (query.riskLevel) where.riskLevel = query.riskLevel;
    if (query.clientId) where.clientId = query.clientId;
    if (query.search) {
      where.OR = [
        { name: { contains: query.search, mode: 'insensitive' } },
        { address: { contains: query.search, mode: 'insensitive' } },
      ];
    }

    const [data, total] = await Promise.all([
      this.prisma.site.findMany({
        where,
        skip,
        take: limit,
        orderBy: { createdAt: 'desc' },
        include: {
          client: { select: { id: true, companyName: true } },
          _count: { select: { guards: true, incidents: true } },
        },
      }),
      this.prisma.site.count({ where }),
    ]);

    return {
      data,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
    };
  }

  async findOne(id: string, organizationId?: string) {
    const where: any = { id };
    if (organizationId) where.organizationId = organizationId;
    const site = await this.prisma.site.findFirst({
      where,
      include: {
        client: true,
        guards: {
          select: {
            id: true,
            fullName: true,
            status: true,
            currentShift: true,
          },
        },
        incidents: { take: 5, orderBy: { createdAt: 'desc' } },
      },
    });
    if (!site) throw new NotFoundException('Site not found');
    return site;
  }

  async create(dto: CreateSiteDto, organizationId: string) {
    return this.prisma.site.create({
      data: {
        organizationId,
        name: dto.name,
        address: dto.address,
        latitude: dto.latitude,
        longitude: dto.longitude,
        clientId: dto.clientId,
        riskLevel: dto.riskLevel,
        targetGuards: dto.targetGuards,
        supervisorId: dto.supervisorId,
        sitePhotos: '[]',
        emergencyContacts: '[]',
        assets: '[]',
      },
    });
  }

  async update(id: string, dto: UpdateSiteDto, organizationId: string) {
    await this.findOne(id, organizationId);
    return this.prisma.site.update({ where: { id }, data: dto as any });
  }

  async remove(id: string, organizationId: string, userId?: string) {
    await this.findOne(id, organizationId);
    const result = await this.prisma.$transaction(async (tx) => {
      // Unlink all guards assigned to this site
      await tx.guard.updateMany({
        where: { assignedSiteId: id },
        data: { assignedSiteId: null },
      });
      // Delete all attendance records for this site
      await tx.attendance.deleteMany({ where: { siteId: id } });
      // Delete patrol logs associated with patrol routes for this site
      const patrolRoutes = await tx.patrolRoute.findMany({
        where: { siteId: id },
        select: { id: true },
      });
      const patrolRouteIds = patrolRoutes.map((pr) => pr.id);
      if (patrolRouteIds.length > 0) {
        await tx.patrolLog.deleteMany({
          where: { patrolRouteId: { in: patrolRouteIds } },
        });
        await tx.patrolRecord.deleteMany({
          where: { routeId: { in: patrolRouteIds } },
        });
        await tx.patrolCheckpoint.deleteMany({
          where: { patrolRouteId: { in: patrolRouteIds } },
        });
        await tx.patrolRoute.deleteMany({
          where: { id: { in: patrolRouteIds } },
        });
      }
      // Delete all incidents for this site
      await tx.incident.deleteMany({ where: { siteId: id } });
      // Delete the site
      return tx.site.delete({ where: { id } });
    });

    // Write audit log (fire-and-forget)
    this.prisma.auditLog
      .create({
        data: {
          userId: userId || '',
          action: 'SITE_DELETED',
          entity: 'Site',
          entityId: id,
          ipAddress: '',
          userAgent: '',
        },
      })
      .catch(() => {});

    return result;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { v2 as cloudinary, UploadApiResponse } from 'cloudinary';

@Injectable()
export class CloudinaryService {
  private readonly logger = new Logger(CloudinaryService.name);
  private configured = false;

  constructor() {
    const cloudName = process.env.CLOUDINARY_CLOUD_NAME;
    const apiKey = process.env.CLOUDINARY_API_KEY;
    const apiSecret = process.env.CLOUDINARY_API_SECRET;

    if (cloudName && apiKey && apiSecret) {
      cloudinary.config({
        cloud_name: cloudName,
        api_key: apiKey,
        api_secret: apiSecret,
      });
      this.configured = true;
      this.logger.log('Cloudinary configured successfully');
    } else {
      this.logger.warn(
        'Cloudinary not configured — set CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET in .env',
      );
    }
  }

  isConfigured(): boolean {
    return this.configured;
  }

  async uploadImage(
    buffer: Buffer,
    folder: string,
  ): Promise<{ url: string; publicId: string }> {
    if (!this.configured) {
      throw new Error('Cloudinary is not configured');
    }

    return new Promise((resolve, reject) => {
      const uploadStream = cloudinary.uploader.upload_stream(
        {
          folder,
          resource_type: 'image',
          transformation: [
            { width: 800, height: 800, crop: 'limit', quality: 'auto' },
          ],
        },
        (error: any, result: UploadApiResponse) => {
          if (error) return reject(error);
          resolve({ url: result.secure_url, publicId: result.public_id });
        },
      );

      const { Readable } = require('stream');
      Readable.from(buffer).pipe(uploadStream);
    });
  }

  async deleteImage(publicId: string): Promise<void> {
    if (!this.configured) return;

    try {
      await cloudinary.uploader.destroy(publicId);
      this.logger.log(`Deleted Cloudinary image: ${publicId}`);
    } catch (error) {
      this.logger.warn(`Failed to delete Cloudinary image: ${publicId}`);
    }
  }

  extractPublicId(url: string): string | null {
    if (!url || !url.includes('cloudinary.com')) return null;

    const match = url.match(/\/upload\/(?:v\d+\/)?(.+)\.\w+$/);
    return match ? match[1] : null;
  }
}
